import { readFrameTopClearance } from './anchored-position'
import {
  nextOverlayId,
  registerOverlayLayer,
  type RegisteredOverlayHandle,
} from './overlay-stack'

/**
 * 纯图标按钮与工具控件的悬停提示（data-hs-tip + 可选 data-hs-kbd 快捷键后缀）：
 * - 停留约 0.45 秒后出现在触发器下方（空间不足自动上翻并避让 --dsh-frame-top-clearance）；
 * - 内置 300ms 连续扫过热身宽限窗（跨过相邻按钮 2~8px 间隙时无需重等 450ms，立刻切换）；
 * - 键盘 :focus-visible 聚焦时同步显示（清理悬停旧定时器防回跳），支持 Escape 单独收起（WCAG 1.4.13）并无损绑定 aria-describedby；
 * - 接入 overlay-stack：在 Modal 内自动抬升 z-index，绝不被模态遮罩压住。
 */
const DELAY = 450
const WARM_GRACE_MS = 300

export function installTooltips(root: HTMLElement): () => void {
  const doc = root.ownerDocument ?? document
  const win = doc.defaultView ?? (typeof window !== 'undefined' ? window : undefined)
  const tip = doc.createElement('div')
  const tipId = nextOverlayId('dsh-tip')
  tip.id = tipId
  tip.className = 'hs-tip'
  tip.setAttribute('role', 'tooltip')
  tip.setAttribute('aria-hidden', 'true')
  tip.setAttribute('data-dsh-portal', '')
  doc.body.appendChild(tip)

  let timer: ReturnType<typeof setTimeout> | undefined
  let current: HTMLElement | undefined
  let describedEl: HTMLElement | undefined
  let prevDescribedBy: string | null = null
  let warmUntil = 0
  let wasVisible = false
  let layerHandle: RegisteredOverlayHandle | null = null

  const detachDescribedBy = () => {
    if (!describedEl) return
    if (prevDescribedBy === null) {
      if (describedEl.getAttribute('aria-describedby') === tipId) {
        describedEl.removeAttribute('aria-describedby')
      }
    } else {
      describedEl.setAttribute('aria-describedby', prevDescribedBy)
    }
    describedEl = undefined
    prevDescribedBy = null
  }

  const attachDescribedBy = (el: HTMLElement) => {
    if (describedEl === el) return
    detachDescribedBy()
    describedEl = el
    prevDescribedBy = el.getAttribute('aria-describedby')
    const tokens = prevDescribedBy ? prevDescribedBy.split(/\s+/).filter(Boolean) : []
    if (!tokens.includes(tipId)) tokens.push(tipId)
    el.setAttribute('aria-describedby', tokens.join(' '))
  }

  const hide = (keepWarm = false) => {
    clearTimeout(timer)
    timer = undefined
    if (wasVisible) {
      warmUntil = keepWarm ? Date.now() + WARM_GRACE_MS : 0
    } else if (!keepWarm) {
      warmUntil = 0
    }
    wasVisible = false
    current = undefined
    detachDescribedBy()
    layerHandle?.dispose()
    layerHandle = null
    tip.classList.remove('hs-tip-on')
    tip.setAttribute('aria-hidden', 'true')
  }

  const renderContent = (el: HTMLElement) => {
    const label = el.dataset.hsTip ?? ''
    const kbd = el.dataset.hsKbd?.trim()
    if (kbd) {
      const labelNode = doc.createElement('span')
      labelNode.textContent = label
      const kbdNode = doc.createElement('span')
      kbdNode.className = 'hs-tip-kbd'
      kbdNode.textContent = kbd
      tip.replaceChildren(labelNode, kbdNode)
    } else {
      tip.textContent = label
    }
  }

  const show = (el: HTMLElement) => {
    renderContent(el)
    layerHandle?.dispose()
    layerHandle = registerOverlayLayer({
      id: tipId,
      tier: 'tooltip',
      doc,
      onEscape: () => {
        hide(false)
      },
    })
    tip.style.zIndex = String(layerHandle.zIndex)

    const r = el.getBoundingClientRect()
    const w = tip.offsetWidth
    const h = tip.offsetHeight
    const vw = win?.innerWidth ?? 1024
    const vh = win?.innerHeight ?? 768
    const topLimit = readFrameTopClearance(8)
    const x = Math.max(8, Math.min(Math.max(8, vw - w - 8), Math.round(r.left + r.width / 2 - w / 2)))
    const preferBottom = Math.round(r.bottom + 6)
    const flipTop = h > 0 && preferBottom + h > vh - 8 && r.top - h - 6 >= topLimit
    const y = flipTop ? Math.round(r.top - h - 6) : preferBottom
    tip.dataset.side = flipTop ? 'top' : 'bottom'
    tip.style.left = `${x}px`
    tip.style.top = `${y}px`
    tip.removeAttribute('aria-hidden')
    tip.classList.add('hs-tip-on')
    attachDescribedBy(el)
    wasVisible = true
  }

  const target = (node: EventTarget | null) =>
    node instanceof Element ? node.closest<HTMLElement>('[data-hs-tip]') ?? undefined : undefined

  const onOver = (e: PointerEvent) => {
    if (e.pointerType === 'touch') return
    const el = target(e.target)
    if (el === current) return
    const warm = tip.classList.contains('hs-tip-on') || Date.now() <= warmUntil
    hide(true)
    if (el === undefined || !(el.dataset.hsTip ?? '').trim()) return
    current = el
    if (warm) {
      show(el)
    } else {
      timer = setTimeout(() => show(el), DELAY)
    }
  }

  const onLeaveRoot = () => {
    hide(false)
  }

  const onPointerDown = () => {
    hide(false)
  }

  const onFocus = (e: FocusEvent) => {
    clearTimeout(timer)
    timer = undefined
    const el = target(e.target)
    if (el !== undefined && (el.dataset.hsTip ?? '').trim()) {
      let focusVisible = true
      try {
        focusVisible = el.matches(':focus-visible')
      } catch {
        focusVisible = true
      }
      if (focusVisible) {
        current = el
        show(el)
      }
    }
  }

  const onFocusOut = () => {
    hide(false)
  }

  const onWindowHide = () => {
    hide(false)
  }

  root.addEventListener('pointerover', onOver)
  root.addEventListener('pointerleave', onLeaveRoot)
  root.addEventListener('pointerdown', onPointerDown)
  root.addEventListener('focusin', onFocus)
  root.addEventListener('focusout', onFocusOut)
  win?.addEventListener('blur', onWindowHide)
  win?.addEventListener('scroll', onWindowHide, true)
  return () => {
    hide(false)
    root.removeEventListener('pointerover', onOver)
    root.removeEventListener('pointerleave', onLeaveRoot)
    root.removeEventListener('pointerdown', onPointerDown)
    root.removeEventListener('focusin', onFocus)
    root.removeEventListener('focusout', onFocusOut)
    win?.removeEventListener('blur', onWindowHide)
    win?.removeEventListener('scroll', onWindowHide, true)
    tip.remove()
  }
}

export const tooltipCss = `
.hs-tip,
.tip-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 8px;
  border-radius: var(--dsw-radius-sm, 8px);
  corner-shape: var(--dsh-corner-shape, var(--dsw-corner-shape, round));
  background: var(--dsw-alias-tooltip-bg);
  color: var(--dsh-tooltip-fg, var(--dsw-alias-label-primary-foreground));
  font-family: var(--dsw-font-family, inherit);
  font-size: var(--dsh-text-sm, 12px);
  font-weight: 400;
  line-height: 1;
  box-shadow: 0 4px 12px rgb(0 0 0 / .18);
  white-space: nowrap;
}
.hs-tip {
  position: fixed;
  z-index: 1000;
  left: 0;
  top: 0;
  padding: 6px 9px;
  pointer-events: none;
  opacity: 0;
  transform-origin: top center;
  transform: translateY(-2px) scale(.96);
  transition:
    opacity var(--dsh-dur-pop, 150ms) var(--dsh-ease-out, cubic-bezier(.22, 1, .36, 1)),
    transform var(--dsh-dur-pop, 150ms) var(--dsh-ease-out, cubic-bezier(.22, 1, .36, 1));
}
.hs-tip[data-side="top"] {
  transform-origin: bottom center;
  transform: translateY(2px) scale(.96);
}
.hs-tip.hs-tip-on {
  opacity: 1;
  transform: none;
}
.hs-tip-kbd,
.tip-kbd {
  padding: 2px 5px;
  border-radius: var(--dsw-radius-xs, 4px);
  corner-shape: var(--dsh-corner-shape, var(--dsw-corner-shape, round));
  background: var(--dsh-tooltip-kbd-bg, color-mix(in srgb, currentColor 16%, transparent));
  font-family: var(--ds-font-family-code, monospace);
  font-size: var(--dsh-text-xs, 11px);
  line-height: 1;
}
@media (prefers-reduced-motion: reduce) {
  .hs-tip {
    transition: none;
  }
}
`
