import React, {
  forwardRef,
  useEffect,
  useRef,
  type CSSProperties,
  type HTMLAttributes,
  type Ref,
  type UIEventHandler,
} from 'react'
import { attachScrollArea, type AttachScrollAreaOptions } from './scroll-area-dom'

export { attachScrollArea, type AttachScrollAreaOptions } from './scroll-area-dom'

function assignRef<T>(ref: Ref<T> | undefined, value: T): void {
  if (!ref) return
  if (typeof ref === 'function') ref(value)
  else (ref as { current: T }).current = value
}

export interface ScrollAreaProps extends Omit<HTMLAttributes<HTMLDivElement>, 'onScroll'> {
  /** 视口最大高度（数字默认转 px）。 */
  maxHeight?: number | string
  /** 边缘渐隐高度（默认 26px）。 */
  fadeSize?: number | string
  /** 流式对话/日志场景：距底 <= 40px 自动贴底，用户上滚触发 150ms 冷却防抢滚动条。 */
  followBottom?: boolean
  /** 显示悬浮细滑块的最小内容高度倍率（默认 2；下拉菜单等可设 1.05）。 */
  thumbThreshold?: number
  /** 透传给内层可滚动视口的类名。 */
  viewportClassName?: string
  /** 透传给内层可滚动视口的内联样式。 */
  viewportStyle?: CSSProperties
  /** 透传给内层可滚动视口的附加语义/事件属性（如 id / role="listbox"）。 */
  viewportProps?: Omit<HTMLAttributes<HTMLDivElement>, 'className' | 'style' | 'onScroll'>
  /** 透传给内层可滚动视口的 ref。 */
  viewportRef?: Ref<HTMLDivElement>
  /** 内层视口滚动回调。 */
  onScroll?: UIEventHandler<HTMLDivElement>
}

export const ScrollArea = forwardRef<HTMLDivElement, ScrollAreaProps>(function ScrollArea(
  {
    maxHeight,
    fadeSize,
    followBottom = false,
    thumbThreshold,
    className,
    style,
    viewportClassName,
    viewportStyle,
    viewportProps,
    viewportRef,
    onScroll,
    children,
    ...rest
  },
  ref,
) {
  const innerViewportRef = useRef<HTMLDivElement | null>(null)

  useEffect(() => {
    const el = innerViewportRef.current
    if (!el) return undefined
    return attachScrollArea(el, { followBottom, thumbThreshold })
  }, [followBottom, thumbThreshold])

  const resolvedViewportStyle: CSSProperties = {
    ...viewportStyle,
    ...(maxHeight !== undefined
      ? { maxHeight: typeof maxHeight === 'number' ? `${maxHeight}px` : maxHeight }
      : {}),
    ...(fadeSize !== undefined
      ? ({
          '--dsh-fade-size': typeof fadeSize === 'number' ? `${fadeSize}px` : fadeSize,
        } as CSSProperties)
      : {}),
  }

  return (
    <div
      ref={ref}
      className={`dsh-scroll-frame${className ? ` ${className}` : ''}`}
      style={style}
      {...rest}
    >
      <div
        {...viewportProps}
        ref={(node) => {
          innerViewportRef.current = node
          assignRef(viewportRef, node)
        }}
        className={`dsh-scroll-area${viewportClassName ? ` ${viewportClassName}` : ''}`}
        style={resolvedViewportStyle}
        onScroll={onScroll}
      >
        {children}
      </div>
      <div className="dsh-scroll-thumb" aria-hidden="true" hidden />
    </div>
  )
})

