/**
 * MiddleTruncate（中部截断）纯逻辑与无框架 DOM 应用器：
 * - splitMiddleTruncate 按码点（Array.from，绝不拆代理对）切分 head / tail，head+tail 拼接严格等于原文；
 * - applyMiddleTruncate 将任意 HTMLElement 原地改造为 .dsh-mtrunc 双段结构（SSR / 原生 DOM 插件通用）；
 * - 本文件禁止引用 React，dist/dom-primitives.js 打包需保持零框架依赖。
 */

export interface MiddleTruncateOptions {
  /** 固定保留末尾 N 个码点（0 < keepEnd < 文本码点长度时生效）。 */
  keepEnd?: number
  /** 语义边界优先级，默认 ['slash']；'slash' 取最后一个 '/'，'dot' 取最后一个 '.'，命中后 tail 从该字符起算。 */
  boundaries?: ReadonlyArray<'slash' | 'dot'>
}

const BOUNDARY_CHARS: Record<'slash' | 'dot', string> = {
  slash: '/',
  dot: '.',
}

/**
 * 计算中部截断的 head / tail 切分：文本总长 ≤ 8 个码点时不截断（tail 为空）；
 * 优先按 keepEnd 定长截尾，其次按 boundaries 语义边界截尾，兜底保留 min(12, max(4, floor(len * 0.35))) 个码点。
 */
export function splitMiddleTruncate(
  text: string,
  options?: MiddleTruncateOptions,
): { head: string; tail: string } {
  const chars = Array.from(text)
  const len = chars.length
  if (len <= 8) return { head: text, tail: '' }

  const keepEnd = options?.keepEnd
  if (typeof keepEnd === 'number' && Number.isFinite(keepEnd) && keepEnd > 0 && keepEnd < len) {
    const tailLen = Math.floor(keepEnd)
    return { head: chars.slice(0, len - tailLen).join(''), tail: chars.slice(len - tailLen).join('') }
  }

  const boundaries = options?.boundaries ?? ['slash']
  for (const boundary of boundaries) {
    const ch = BOUNDARY_CHARS[boundary]
    if (ch === undefined) continue
    const idx = chars.lastIndexOf(ch)
    if (idx > 0 && idx < len - 1) {
      return { head: chars.slice(0, idx).join(''), tail: chars.slice(idx).join('') }
    }
  }

  const tailLen = Math.min(12, Math.max(4, Math.floor(len * 0.35)))
  return { head: chars.slice(0, len - tailLen).join(''), tail: chars.slice(len - tailLen).join('') }
}

/**
 * 将 el 原地改造为中部截断结构：补挂 .dsh-mtrunc 类、写入 title 全文提示，
 * 子节点替换为 .dsh-mtrunc-head / .dsh-mtrunc-tail 两个 span（屏幕阅读器可连读完整原文）。
 */
export function applyMiddleTruncate(
  el: HTMLElement,
  text: string,
  options?: MiddleTruncateOptions,
): void {
  const { head, tail } = splitMiddleTruncate(text, options)
  const doc = el.ownerDocument
  if (el.classList && typeof el.classList.add === 'function') {
    el.classList.add('dsh-mtrunc')
  } else {
    const existing = String(el.className ?? '').split(/\s+/).filter(Boolean)
    if (!existing.includes('dsh-mtrunc')) {
      el.className = [...existing, 'dsh-mtrunc'].join(' ')
    }
  }
  el.setAttribute('title', text)
  el.textContent = ''
  for (const child of Array.from(el.children ?? [])) {
    ;(child as HTMLElement).remove?.()
  }

  const headSpan = doc.createElement('span')
  headSpan.className = 'dsh-mtrunc-head'
  headSpan.textContent = head
  el.appendChild(headSpan)

  if (tail) {
    const tailSpan = doc.createElement('span')
    tailSpan.className = 'dsh-mtrunc-tail'
    tailSpan.textContent = tail
    el.appendChild(tailSpan)
  }
}

/**
 * 中部截断双段样式：外层 inline-flex 整体参与行内排版，head 段可收缩带省略号，
 * tail 段定长不缩、超宽时自身以 70% 上限二次省略，保证文件名 / 模型 ID 尾缀始终可读。
 */
export const middleTruncateCss = `
.dsh-mtrunc {
  display: inline-flex;
  min-width: 0;
  max-width: 100%;
  white-space: nowrap;
  overflow: hidden;
  vertical-align: bottom;
}
.dsh-mtrunc-head {
  flex: 0 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.dsh-mtrunc-tail {
  flex: 0 0 auto;
  max-width: 70%;
  overflow: hidden;
  text-overflow: ellipsis;
}
`
