import {
  createContext,
  useContext,
  useEffect,
  useId,
  useLayoutEffect,
  useRef,
  useState,
} from 'react'
import { isImeComposing } from './host-bridge'

export type OverlayTier =
  | 'tooltip'
  | 'menu'
  | 'popover'
  | 'select'
  | 'infotip'
  | 'modal'
  | 'toast'

export const OVERLAY_BASE_Z: Readonly<Record<OverlayTier, number>> = {
  tooltip: 1000,
  menu: 1100,
  popover: 1100,
  select: 1150,
  infotip: 1150,
  modal: 1200,
  toast: 1400,
}

/**
 * 逻辑父浮层上下文：
 * 让 Portal 到 document.body 的子浮层（如 PopoverRow 内的 InfoTip、Modal 内的 Select / Popover）
 * 在组件树上自动继承父浮层 ID，使外部点击判定将逻辑子孙浮层识别为「内部点击」而非误关父层。
 */
export const OverlayParentContext = createContext<string | null>(null)

export interface OverlayLayerEntry {
  id: string
  tier: OverlayTier
  parentId?: string | null
  doc?: Document
  /** 判断目标节点是否属于当前浮层自身（如触发器或浮层面板内部）。 */
  containsNode?: (node: Node) => boolean
  /** 栈顶按 Escape 时的回调；返回 false 表示本层不消费该次 Escape，继续向下一层传递。 */
  onEscape?: (event: KeyboardEvent) => boolean | void
  /** 点击在当前层及其全部逻辑子孙层之外时的回调。 */
  onPointerDownOutside?: (event: PointerEvent) => void
}

interface InternalLayerRecord extends OverlayLayerEntry {
  zIndex: number
  doc: Document
}

interface DocDispatcher {
  layers: InternalLayerRecord[]
  cleanup: () => void
}

const docDispatchers = new WeakMap<Document, DocDispatcher>()
const consumedOutsideEvents = new WeakSet<Event>()

function isDomNode(value: unknown): value is Node {
  return (
    typeof value === 'object'
    && value !== null
    && typeof (value as { nodeType?: unknown }).nodeType === 'number'
  )
}

export function wasPointerDownConsumedByUpperLayer(event: unknown): boolean {
  if (typeof event !== 'object' || event === null) return false
  if (consumedOutsideEvents.has(event as Event)) return true
  const native = (event as { nativeEvent?: unknown }).nativeEvent
  if (typeof native === 'object' && native !== null && consumedOutsideEvents.has(native as Event)) {
    return true
  }
  return false
}

function isDescendantOrSelfLayer(
  layers: readonly InternalLayerRecord[],
  candidate: InternalLayerRecord,
  ancestorId: string,
): boolean {
  let cur: InternalLayerRecord | undefined = candidate
  const visited = new Set<string>()
  while (cur) {
    if (cur.id === ancestorId) return true
    if (!cur.parentId || visited.has(cur.id)) break
    visited.add(cur.id)
    const pid: string = cur.parentId
    cur = layers.find((item) => item.id === pid)
  }
  return false
}

function isNodeInsideLayerTree(
  layers: readonly InternalLayerRecord[],
  layer: InternalLayerRecord,
  target: Node,
): boolean {
  for (const item of layers) {
    if (isDescendantOrSelfLayer(layers, item, layer.id)) {
      if (item.containsNode?.(target) === true) return true
    }
  }
  return false
}

function computeLayerZIndex(
  layers: readonly InternalLayerRecord[],
  tier: OverlayTier,
): number {
  const base = OVERLAY_BASE_Z[tier]
  if (tier === 'toast') {
    let maxAll = base - 10
    for (const item of layers) {
      if (item.zIndex > maxAll) maxAll = item.zIndex
    }
    return Math.max(base, maxAll + 10)
  }

  let maxBelowToast = 0
  for (const item of layers) {
    if (item.tier !== 'toast' && item.zIndex > maxBelowToast) {
      maxBelowToast = item.zIndex
    }
  }
  return maxBelowToast >= base ? maxBelowToast + 10 : base
}

function ensureDocDispatcher(doc: Document): DocDispatcher {
  const existing = docDispatchers.get(doc)
  if (existing) return existing

  const layers: InternalLayerRecord[] = []

  const onKeyDown = (event: KeyboardEvent) => {
    if (event.key !== 'Escape') return
    if (event.defaultPrevented || isImeComposing(event)) return

    const activeEl = doc.activeElement
    const consumeLayer = (layer: InternalLayerRecord): boolean => {
      if (!layer.onEscape) return false
      const handled = layer.onEscape(event)
      if (handled !== false) {
        event.preventDefault?.()
        event.stopPropagation?.()
        if (typeof event.stopImmediatePropagation === 'function') {
          event.stopImmediatePropagation()
        }
        return true
      }
      return false
    }

    // 若当前焦点就在某条 Toast 内部，优先允许 Esc 直接收起该 Toast
    if (activeEl) {
      for (let i = layers.length - 1; i >= 0; i -= 1) {
        const layer = layers[i]
        if (layer?.tier === 'toast' && layer.containsNode?.(activeEl) === true) {
          if (consumeLayer(layer)) return
        }
      }
    }

    // 优先由非 Toast 交互浮层（Tooltip / InfoTip / Select / Menu / Popover / Modal）按 LIFO 栈顶消费 Esc
    for (let i = layers.length - 1; i >= 0; i -= 1) {
      const layer = layers[i]
      if (!layer || layer.tier === 'toast') continue
      if (consumeLayer(layer)) return
    }

    // 无任何交互浮层打开时，允许 Esc 收起被动悬浮的 Toast
    for (let i = layers.length - 1; i >= 0; i -= 1) {
      const layer = layers[i]
      if (layer?.tier === 'toast' && consumeLayer(layer)) return
    }
  }

  const onPointerDownCapture = (event: PointerEvent) => {
    const target = event.target
    if (!isDomNode(target)) return

    for (let i = layers.length - 1; i >= 0; i -= 1) {
      const layer = layers[i]
      if (!layer) continue

      if (isNodeInsideLayerTree(layers, layer, target)) {
        // 点击落在当前栈顶（或更高层）内部，属于合法层内操作，不得向更底层判外部点击
        return
      }

      if (layer.onPointerDownOutside) {
        consumedOutsideEvents.add(event)
        layer.onPointerDownOutside(event)
        // 每次点击最多剥离最顶上一层浮动弹层，防止点一次同时关掉子菜单和底层 Modal / Popover
        return
      }

      if (layer.tier === 'modal') {
        // 遇到模态阻断层即停止向下穿透
        return
      }
    }
  }

  doc.addEventListener('keydown', onKeyDown)
  doc.addEventListener('pointerdown', onPointerDownCapture, true)

  const dispatcher: DocDispatcher = {
    layers,
    cleanup: () => {
      doc.removeEventListener('keydown', onKeyDown)
      doc.removeEventListener('pointerdown', onPointerDownCapture, true)
      docDispatchers.delete(doc)
    },
  }

  docDispatchers.set(doc, dispatcher)
  return dispatcher
}

export interface RegisteredOverlayHandle {
  zIndex: number
  dispose: () => void
}

let imperativeLayerSeq = 0

export function nextOverlayId(prefix = 'dsh-ov'): string {
  imperativeLayerSeq += 1
  return `${prefix}-${imperativeLayerSeq}`
}

/**
 * 命令式浮层入栈注册器（供 Tooltip 等非 React 原语与 useOverlayLayer 共享）：
 * 自动分配不倒挂的动态 zIndex，并在栈空时自动卸载全局 document 监听。
 */
export function registerOverlayLayer(entry: OverlayLayerEntry): RegisteredOverlayHandle {
  const doc = entry.doc ?? (typeof document !== 'undefined' ? document : undefined)
  const fallbackZ = OVERLAY_BASE_Z[entry.tier]
  if (!doc) {
    return { zIndex: fallbackZ, dispose: () => {} }
  }

  const dispatcher = ensureDocDispatcher(doc)
  const existingIdx = dispatcher.layers.findIndex((item) => item.id === entry.id)
  if (existingIdx >= 0) {
    dispatcher.layers.splice(existingIdx, 1)
  }

  const zIndex = computeLayerZIndex(dispatcher.layers, entry.tier)
  const record: InternalLayerRecord = {
    ...entry,
    doc,
    zIndex,
  }
  dispatcher.layers.push(record)

  let disposed = false
  return {
    zIndex,
    dispose: () => {
      if (disposed) return
      disposed = true
      const idx = dispatcher.layers.indexOf(record)
      if (idx >= 0) {
        dispatcher.layers.splice(idx, 1)
      }
      if (dispatcher.layers.length === 0) {
        dispatcher.cleanup()
      }
    },
  }
}

export interface UseOverlayLayerOptions {
  open: boolean
  tier: OverlayTier
  containsNode?: (node: Node) => boolean
  onEscape?: (event: KeyboardEvent) => boolean | void
  onPointerDownOutside?: (event: PointerEvent) => void
  closeOnEscape?: boolean
}

export interface UseOverlayLayerResult {
  layerId: string
  zIndex: number
}

/**
 * React 浮层栈 Hook：
 * - 自动接入 OverlayParentContext 建立逻辑父子链；
 * - 同步计算高于父模态/浮层的动态 zIndex；
 * - 统一 LIFO Escape 与外部 pointerdown 关闭，消除多监听竞态与双重关闭。
 */
export function useOverlayLayer({
  open,
  tier,
  containsNode,
  onEscape,
  onPointerDownOutside,
  closeOnEscape = true,
}: UseOverlayLayerOptions): UseOverlayLayerResult {
  const reactId = useId()
  const layerId = `dsh-layer-${reactId.replaceAll(':', '')}`
  const parentId = useContext(OverlayParentContext)
  const [zIndex, setZIndex] = useState<number>(() => OVERLAY_BASE_Z[tier])

  const callbacksRef = useRef({
    containsNode,
    onEscape,
    onPointerDownOutside,
    closeOnEscape,
  })
  callbacksRef.current = {
    containsNode,
    onEscape,
    onPointerDownOutside,
    closeOnEscape,
  }

  const useClientLayoutEffect = typeof document !== 'undefined' ? useLayoutEffect : useEffect

  useClientLayoutEffect(() => {
    if (!open || typeof document === 'undefined') {
      setZIndex(OVERLAY_BASE_Z[tier])
      return undefined
    }

    const handle = registerOverlayLayer({
      id: layerId,
      tier,
      parentId,
      doc: document,
      containsNode: (node) => callbacksRef.current.containsNode?.(node) ?? false,
      onEscape: (event) => {
        if (!callbacksRef.current.closeOnEscape || !callbacksRef.current.onEscape) {
          return false
        }
        return callbacksRef.current.onEscape(event)
      },
      onPointerDownOutside: callbacksRef.current.onPointerDownOutside
        ? (event) => callbacksRef.current.onPointerDownOutside?.(event)
        : undefined,
    })

    setZIndex((prev) => (prev === handle.zIndex ? prev : handle.zIndex))
    return () => {
      handle.dispose()
    }
  }, [open, tier, layerId, parentId])

  return { layerId, zIndex }
}

/* ---------- 多层 Modal 共享的兄弟 inert 引用计数锁 ---------- */

type InertCapableElement = Element & { inert?: boolean }

interface InertSlot {
  count: number
  hadAttr: boolean
  prevProp: boolean
}

const inertRefMap = new WeakMap<Element, InertSlot>()

export function acquireModalInert(doc: Document, activeOverlayEl: Element | null): () => void {
  if (!doc.body || !activeOverlayEl || activeOverlayEl.parentElement !== doc.body) {
    return () => {}
  }

  const locked: InertCapableElement[] = []
  for (const sibling of Array.from(doc.body.children)) {
    if (
      sibling === activeOverlayEl
      || sibling.tagName === 'SCRIPT'
      || sibling.tagName === 'STYLE'
      || sibling.hasAttribute('data-dsh-toast')
      || sibling.hasAttribute('data-dsh-portal')
    ) {
      continue
    }
    const el = sibling as InertCapableElement
    const existing = inertRefMap.get(el)
    if (existing) {
      existing.count += 1
    } else {
      inertRefMap.set(el, {
        count: 1,
        hadAttr: el.hasAttribute('inert'),
        prevProp: Boolean(el.inert),
      })
    }
    el.inert = true
    el.setAttribute('inert', '')
    locked.push(el)
  }

  let released = false
  return () => {
    if (released) return
    released = true
    for (const el of locked) {
      const slot = inertRefMap.get(el)
      if (!slot) continue
      slot.count -= 1
      if (slot.count <= 0) {
        inertRefMap.delete(el)
        el.inert = slot.prevProp
        if (slot.hadAttr) el.setAttribute('inert', '')
        else el.removeAttribute('inert')
      }
    }
  }
}
