import {
  useEffect,
  useLayoutEffect,
  useState,
  type CSSProperties,
  type RefObject,
} from 'react'

export type AnchoredSide = 'top' | 'bottom' | 'right' | 'left'
export type AnchoredAlign = 'start' | 'end'

export interface AnchoredRectLike {
  left: number
  top: number
  right: number
  bottom: number
}

export interface AnchoredPlacement {
  left: number
  top: number
  side: AnchoredSide
  align: AnchoredAlign
  maxHeight: number
  origin: string
}

export interface ComputeAnchoredPlacementOptions {
  side?: AnchoredSide
  align?: AnchoredAlign
  gap: number
  margin: number
  topClearance?: number
  flip?: boolean
}

export function readFrameTopClearance(margin: number): number {
  if (typeof document === 'undefined' || typeof getComputedStyle !== 'function') {
    return margin
  }
  const root = document.documentElement
  if (!root) return margin
  const clearance = Number.parseFloat(
    getComputedStyle(root).getPropertyValue('--dsh-frame-top-clearance'),
  )
  return Number.isNaN(clearance)
    ? margin
    : Math.max(margin, (root.hasAttribute('data-fullscreen') ? 0 : clearance) + 20)
}

/**
 * 纯几何锚定计算（边缘碰撞翻转 + 安全视口夹紧 + 可用净高 + 动态展开原点）：
 * - 首选方向空间不足且对侧空间更充裕时自动翻转（避免底边硬夹紧盖住触发器本身）；
 * - 窄屏/矮屏统一采用 Math.min(Math.max(raw, min), Math.max(min, max))，绝不跌破左界或顶部 macOS 标题栏安全区；
 * - 动态反算指向触发器中心的 transform-origin 与该侧最大可用高度 maxHeight。
 */
export function computeAnchoredPlacement(
  anchor: AnchoredRectLike,
  panelSize: { width: number; height: number },
  viewport: { width: number; height: number },
  options: ComputeAnchoredPlacementOptions,
): AnchoredPlacement {
  const {
    side = 'bottom',
    align = 'start',
    gap,
    margin,
    topClearance,
    flip = true,
  } = options
  const topLimit = Math.max(margin, topClearance ?? margin)
  const { width, height } = panelSize

  if (side === 'right' || side === 'left') {
    const availRight = Math.max(0, viewport.width - anchor.right - gap - margin)
    const availLeft = Math.max(0, anchor.left - gap - margin)
    let resolvedSide: 'right' | 'left' = side
    if (flip && width > 0) {
      if (side === 'right' && width > availRight && availLeft > availRight) {
        resolvedSide = 'left'
      } else if (side === 'left' && width > availLeft && availRight > availLeft) {
        resolvedSide = 'right'
      }
    }

    const rawLeft = resolvedSide === 'left' ? anchor.left - gap - width : anchor.right + gap
    const rawTop = align === 'end' ? anchor.bottom - height : anchor.top
    const left =
      width > 0
        ? Math.min(Math.max(rawLeft, margin), Math.max(margin, viewport.width - width - margin))
        : rawLeft
    const top =
      height > 0
        ? Math.min(Math.max(rawTop, topLimit), Math.max(topLimit, viewport.height - height - margin))
        : rawTop
    const maxHeight = Math.max(96, Math.floor(viewport.height - topLimit - margin))
    const origin = `${resolvedSide === 'left' ? 'right' : 'left'} ${align === 'end' ? 'bottom' : 'top'}`

    return {
      left: Math.round(left),
      top: Math.round(top),
      side: resolvedSide,
      align,
      maxHeight,
      origin,
    }
  }

  const availBelow = Math.max(0, viewport.height - anchor.bottom - gap - margin)
  const availAbove = Math.max(0, anchor.top - gap - topLimit)
  let resolvedSide: 'top' | 'bottom' = side
  if (flip && height > 0) {
    if (side === 'bottom' && height > availBelow && availAbove > availBelow) {
      resolvedSide = 'top'
    } else if (side === 'top' && height > availAbove && availBelow > availAbove) {
      resolvedSide = 'bottom'
    }
  }

  const rawLeft = align === 'end' ? anchor.right - width : anchor.left
  const rawTop = resolvedSide === 'top' ? anchor.top - gap - height : anchor.bottom + gap

  const left =
    width > 0
      ? Math.min(Math.max(rawLeft, margin), Math.max(margin, viewport.width - width - margin))
      : rawLeft
  const top =
    height > 0
      ? Math.min(Math.max(rawTop, topLimit), Math.max(topLimit, viewport.height - height - margin))
      : rawTop

  const availSideHeight = resolvedSide === 'top' ? availAbove : availBelow
  const maxHeight = Math.max(96, Math.floor(availSideHeight))

  const anchorCenterX = (anchor.left + anchor.right) / 2
  const origin =
    width > 0
      ? `${Math.round(Math.min(Math.max(anchorCenterX - left, 8), Math.max(8, width - 8)))}px ${resolvedSide === 'top' ? 'bottom' : 'top'}`
      : `${align === 'end' ? 'right' : 'left'} ${resolvedSide === 'top' ? 'bottom' : 'top'}`

  return {
    left: Math.round(left),
    top: Math.round(top),
    side: resolvedSide,
    align,
    maxHeight,
    origin,
  }
}

export interface UseAnchoredPlacementOptions {
  open: boolean
  anchorRef: RefObject<HTMLElement | null>
  panelRef: RefObject<HTMLElement | null>
  /** 默认 bottom。 */
  side?: AnchoredSide
  /** 默认 start（左边对齐锚点左边）。 */
  align?: AnchoredAlign
  gap: number
  margin: number
  /** 空间不足时是否自动翻转到对侧（默认 true）。 */
  flip?: boolean
}

/**
 * 完整锚定方位 Hook：返回坐标、翻转后的实际 side、可用 maxHeight 与指向触发器的 origin。
 * SSR 安全（服务端回退 useEffect 无告警），同时监听窗口缩放、祖先滚动及锚点/面板双端尺寸变化。
 */
export function useAnchoredPlacement(
  options: UseAnchoredPlacementOptions,
): AnchoredPlacement | null {
  const {
    open,
    anchorRef,
    panelRef,
    side = 'bottom',
    align = 'start',
    gap,
    margin,
    flip = true,
  } = options
  const [placement, setPlacement] = useState<AnchoredPlacement | null>(null)
  const useClientLayoutEffect = typeof document !== 'undefined' ? useLayoutEffect : useEffect

  useClientLayoutEffect(() => {
    if (!open || typeof window === 'undefined') {
      setPlacement((prev) => (prev === null ? prev : null))
      return undefined
    }

    const measure = () => {
      const anchorEl = anchorRef.current
      const anchor = anchorEl?.getBoundingClientRect()
      if (!anchor) return
      const panel = panelRef.current
      const width = panel?.offsetWidth ?? 0
      const height = panel?.offsetHeight ?? 0
      const vv = window.visualViewport
      const vw = vv?.width ?? window.innerWidth
      const vh = vv?.height ?? window.innerHeight
      const next = computeAnchoredPlacement(
        anchor,
        { width, height },
        { width: vw, height: vh },
        {
          side,
          align,
          gap,
          margin,
          topClearance: readFrameTopClearance(margin),
          flip,
        },
      )
      setPlacement((prev) =>
        prev
        && prev.left === next.left
        && prev.top === next.top
        && prev.side === next.side
        && prev.align === next.align
        && prev.maxHeight === next.maxHeight
        && prev.origin === next.origin
          ? prev
          : next,
      )
    }

    const onScroll = (event: Event) => {
      const anchor = anchorRef.current
      if (anchor === null) return
      const target = event.target
      if (
        target === window
        || target === document
        || (target instanceof Node && target !== anchor && target.contains(anchor))
      ) {
        measure()
      }
    }

    measure()
    window.addEventListener('scroll', onScroll, true)
    window.addEventListener('resize', measure)
    const vv = window.visualViewport
    vv?.addEventListener?.('resize', measure)
    vv?.addEventListener?.('scroll', measure)

    let observer: ResizeObserver | null = null
    if (typeof ResizeObserver !== 'undefined') {
      observer = new ResizeObserver(measure)
      if (panelRef.current !== null) observer.observe(panelRef.current)
      if (anchorRef.current !== null) observer.observe(anchorRef.current)
    }

    return () => {
      observer?.disconnect()
      window.removeEventListener('scroll', onScroll, true)
      window.removeEventListener('resize', measure)
      vv?.removeEventListener?.('resize', measure)
      vv?.removeEventListener?.('scroll', measure)
    }
  }, [open, anchorRef, panelRef, side, align, gap, margin, flip])

  return placement
}

/**
 * 统一浮层锚定定位（保持 { left, top } 兼容签名）：
 * 底层委托至 useAnchoredPlacement，自动具备边缘翻转与标题栏安全夹紧。
 */
export function useAnchoredPosition(options: {
  open: boolean
  anchorRef: RefObject<HTMLElement | null>
  panelRef: RefObject<HTMLElement | null>
  /** 默认 bottom。 */
  side?: 'top' | 'bottom'
  /** 默认 start（左边对齐锚点左边）。 */
  align?: 'start' | 'end'
  gap: number
  margin: number
}): CSSProperties | null {
  const placement = useAnchoredPlacement(options)
  if (placement === null) return null
  return { left: placement.left, top: placement.top }
}
