import React, {
  cloneElement,
  useEffect,
  useRef,
  type ComponentType,
  type CSSProperties,
  type KeyboardEvent as ReactKeyboardEvent,
  type PointerEvent as ReactPointerEvent,
  type ReactElement,
  type ReactNode,
} from 'react'
import { createPortal } from 'react-dom'
import { MenuSurface } from './MenuSurface'
import { Modal } from './Modal'
import { useAnchoredPlacement } from './anchored-position'
import { isImeComposing } from './host-bridge'
import { CheckIcon } from './icons'
import { didPointerActuallyMove } from './motion'
import { OverlayParentContext, useOverlayLayer } from './overlay-stack'

/**
 * 官方 @deepseek-ai/dsh-client-ui-primitives 的安全垫片：
 * 复杂交互组件（菜单、对话框、悬浮卡片、悬停提示、开关）优先取宿主官方导出，
 * 但全部包裹在 try/catch 里逐项读取——任何一项缺失或改名时仅退化该项，绝不导致插件客户端整体崩溃。
 * 退化组件与标准件采用完全一致的同心圆角（标准菜单项 12px / 紧凑 8px、弹窗委托 Modal 16px、开关 36x20 正圆滑块）与双轨曲率规则。
 */

declare const require: ((id: string) => unknown) | undefined

const PACKAGE = '@deepseek-ai/dsh-client-ui-primitives'

export type MenuItem =
  | { type: 'label', id: string, text: string }
  | { type: 'separator', id: string }
  | {
    type?: undefined
    id: string
    label: string
    disabled?: boolean
    icon?: ReactNode
    danger?: boolean
    shortcut?: string
    submenu?: readonly MenuItem[]
  }

export interface MenuProps {
  open: boolean
  onClose: () => void
  anchor: ReactElement
  items?: readonly MenuItem[]
  selectedIds?: readonly string[]
  onSelect?: (id: string) => void
  align?: 'start' | 'end'
  side?: 'bottom' | 'top' | 'right'
  compact?: boolean
  footer?: ReactNode
  maxHeight?: number | string
  portal?: boolean
  closeOnPointerLeave?: boolean
  children?: ReactNode
}

export interface MenuItemButtonProps {
  icon?: ReactNode
  shortcut?: string
  danger?: boolean
  disabled?: boolean
  separatorBefore?: boolean
  onSelect: () => void
  children?: ReactNode
}

export interface TooltipProps {
  label: string
  shortcutKeys?: readonly string[]
  side?: 'top' | 'bottom' | 'left' | 'right'
  align?: 'start' | 'center' | 'end'
  delayMs?: number
  portal?: boolean
  children: ReactElement
}

export interface HoverCardProps {
  anchor: ReactElement
  content: ReactNode
  openDelayMs?: number
  grouped?: boolean
  disabled?: boolean
  copyText?: string
  copyLabel?: string
  copiedLabel?: string
}

export interface ModalProps {
  open: boolean
  onClose: () => void
  closeLabel?: string
  title: string
  description?: string
  footer?: ReactNode
  children?: ReactNode
}

export interface SwitchProps {
  checked: boolean
  label: string
  disabled?: boolean
  onChange: (checked: boolean) => void
}

export type Primitives = {
  Menu: ComponentType<MenuProps>
  MenuItemButton: ComponentType<MenuItemButtonProps>
  Modal: ComponentType<ModalProps>
  HoverCard: ComponentType<HoverCardProps>
  Tooltip: ComponentType<TooltipProps>
  Switch: ComponentType<SwitchProps>
}

type Name = keyof Primitives

function loadOfficial(): unknown {
  try {
    return typeof require === 'function' ? require(PACKAGE) : undefined
  } catch {
    return undefined
  }
}

function isComponent(value: unknown): boolean {
  return typeof value === 'function' || (typeof value === 'object' && value !== null && '$$typeof' in value)
}

export function resolvePrimitives(
  load: () => unknown = loadOfficial,
  warn: (message: string) => void = message => console.warn(message),
  scope = 'harness-plus',
): Primitives {
  let mod: unknown
  let loadError: unknown
  try {
    mod = load()
  } catch (error) {
    loadError = error
  }
  const missing: Name[] = []
  const pick = <K extends Name>(name: K): Primitives[K] => {
    let value: unknown
    try {
      value = typeof mod === 'object' && mod !== null ? (mod as Record<string, unknown>)[name] : undefined
    } catch {
      value = undefined
    }
    if (isComponent(value)) return value as Primitives[K]
    missing.push(name)
    return FALLBACKS[name] as Primitives[K]
  }
  const resolved: Primitives = {
    Menu: pick('Menu'),
    MenuItemButton: pick('MenuItemButton'),
    Modal: pick('Modal'),
    HoverCard: pick('HoverCard'),
    Tooltip: pick('Tooltip'),
    Switch: pick('Switch'),
  }
  if (missing.length > 0) {
    const why = mod === undefined || mod === null
      ? `加载不到 ${PACKAGE}${loadError === undefined ? '' : `（${String(loadError)}）`}`
      : `${PACKAGE} 缺少导出`
    warn(`[${scope}] ${why}，以下组件改用简化版本：${missing.join('、')}`)
  }
  return resolved
}

/* ---------- 退化与可独立复用的标准组件 ---------- */

function FallbackTooltip({ children }: TooltipProps) {
  return children
}

function FallbackHoverCard({ anchor }: HoverCardProps) {
  return anchor
}

/** 标准 36x20 开关（正圆 16px 滑块，按压微伸展 20px，显式 corner-shape: round 避免被超椭圆压扁）。 */
export function StandaloneSwitch({ checked, label, disabled = false, onChange }: SwitchProps) {
  return (
    <button
      type="button"
      role="switch"
      aria-checked={checked}
      aria-label={label}
      disabled={disabled}
      className="hs-fb-switch"
      onClick={(event) => {
        event.stopPropagation?.()
        if (!disabled) onChange(!checked)
      }}
    >
      <span className="hs-fb-thumb" aria-hidden="true" />
    </button>
  )
}

function FallbackMenuItemButton({
  icon,
  shortcut,
  danger = false,
  disabled = false,
  separatorBefore = false,
  onSelect,
  children,
}: MenuItemButtonProps) {
  return (
    <>
      {separatorBefore && <div className="hs-fb-sep" role="separator" />}
      <button
        type="button"
        role="menuitem"
        disabled={disabled}
        className={`hs-fb-item${danger ? ' hs-fb-danger' : ''}`}
        onClick={onSelect}
      >
        {icon !== undefined && <span aria-hidden="true" className="hs-fb-icon">{icon}</span>}
        <span className="hs-fb-label">{children}</span>
        {shortcut !== undefined && <span aria-hidden="true" className="hs-fb-kbd">{shortcut}</span>}
      </button>
    </>
  )
}

const HIDDEN: CSSProperties = { left: 0, top: 0, visibility: 'hidden' }

function findAnchorTrigger(anchorWrap: HTMLElement | null): HTMLElement | null {
  if (!anchorWrap) return null
  const found = anchorWrap.querySelector<HTMLElement>('button, a, input, [tabindex]')
  if (found) return found
  const firstChild = anchorWrap.children?.[0]
  return firstChild instanceof HTMLElement ? firstChild : null
}

function FallbackMenu({
  open,
  onClose,
  anchor,
  items = [],
  selectedIds,
  onSelect,
  align = 'start',
  side = 'bottom',
  compact = false,
  footer,
  maxHeight,
  portal = true,
  closeOnPointerLeave = false,
  children,
}: MenuProps) {
  const anchorRef = useRef<HTMLSpanElement>(null)
  const panelRef = useRef<HTMLDivElement>(null)
  const lastPointerRef = useRef<{ x: number; y: number } | null>(null)
  const onCloseRef = useRef(onClose)
  onCloseRef.current = onClose

  const hasSelectionMode = selectedIds !== undefined
  const placement = useAnchoredPlacement({
    open,
    anchorRef,
    panelRef,
    side,
    align,
    gap: 4,
    margin: 12,
  })

  const restoreFocusToAnchor = () => {
    const triggerEl = findAnchorTrigger(anchorRef.current)
    triggerEl?.focus?.()
  }

  const { layerId, zIndex } = useOverlayLayer({
    open,
    tier: 'menu',
    containsNode: (node) =>
      Boolean(anchorRef.current?.contains(node) || panelRef.current?.contains(node)),
    onEscape: () => {
      restoreFocusToAnchor()
      onCloseRef.current()
    },
    onPointerDownOutside: () => {
      onCloseRef.current()
    },
  })

  const syncHighlightedEl = (nextEl: HTMLElement | null) => {
    const panel = panelRef.current
    if (!panel) return
    const all = Array.from(panel.querySelectorAll<HTMLElement>('.hs-fb-item'))
    for (const item of all) {
      if (nextEl !== null && item === nextEl) {
        item.setAttribute('data-highlighted', 'true')
      } else {
        item.removeAttribute('data-highlighted')
      }
    }
  }

  useEffect(() => {
    if (!open || typeof document === 'undefined') {
      lastPointerRef.current = null
      return undefined
    }
    const panel = panelRef.current
    if (panel && !panel.contains(document.activeElement)) {
      panel.focus?.({ preventScroll: true })
    }
    return () => {
      const doc = panel?.ownerDocument ?? document
      const active = doc?.activeElement
      if (active && (panel?.contains(active) || active === doc.body)) {
        restoreFocusToAnchor()
      }
    }
  }, [open])

  const renderEntry = (item: MenuItem): ReactNode => {
    if (item.type === 'label') return <div key={item.id} className="hs-fb-heading">{item.text}</div>
    if (item.type === 'separator') return <div key={item.id} className="hs-fb-sep" role="separator" />
    if (item.submenu !== undefined) {
      if (item.submenu.length === 0) return null
      return (
        <div key={item.id} role="group" aria-label={item.label} className="hs-fb-group">
          <div className="hs-fb-heading">{item.label}</div>
          {item.submenu.map(renderEntry)}
          <div className="hs-fb-sep" role="separator" />
        </div>
      )
    }
    const checked = hasSelectionMode ? selectedIds.includes(item.id) : false
    return (
      <button
        key={item.id}
        type="button"
        role={hasSelectionMode ? 'menuitemcheckbox' : 'menuitem'}
        aria-checked={hasSelectionMode ? checked : undefined}
        disabled={item.disabled}
        className={`hs-fb-item${item.danger === true ? ' hs-fb-danger' : ''}`}
        onClick={() => onSelect?.(item.id)}
      >
        {item.icon !== undefined && <span aria-hidden="true" className="hs-fb-icon">{item.icon}</span>}
        <span className="hs-fb-label">{item.label}</span>
        {checked && (
          <span className="hs-fb-check" aria-hidden="true">
            <CheckIcon />
          </span>
        )}
        {item.shortcut !== undefined && <span aria-hidden="true" className="hs-fb-kbd">{item.shortcut}</span>}
      </button>
    )
  }

  const handleMenuKeyDown = (event: ReactKeyboardEvent<HTMLDivElement>) => {
    if (isImeComposing(event)) return
    if (event.key === 'Tab') {
      restoreFocusToAnchor()
      onCloseRef.current()
      return
    }
    if (event.key === 'Escape') {
      event.preventDefault()
      event.stopPropagation?.()
      restoreFocusToAnchor()
      onCloseRef.current()
      return
    }
    if (
      event.key !== 'ArrowDown'
      && event.key !== 'ArrowUp'
      && event.key !== 'Home'
      && event.key !== 'End'
    ) {
      return
    }
    const panel = panelRef.current
    if (!panel) return
    const list = Array.from(panel.querySelectorAll<HTMLButtonElement>('.hs-fb-item')).filter(
      (el) => !el.disabled,
    )
    if (list.length === 0) return
    event.preventDefault()
    const doc = panel.ownerDocument
    const focusedIdx = doc ? list.indexOf(doc.activeElement as HTMLButtonElement) : -1
    const highlightedIdx = list.findIndex((el) => el.getAttribute('data-highlighted') === 'true')
    const curIdx = highlightedIdx >= 0 ? highlightedIdx : focusedIdx
    let nextIdx = 0
    if (event.key === 'Home') {
      nextIdx = 0
    } else if (event.key === 'End') {
      nextIdx = list.length - 1
    } else if (event.key === 'ArrowDown') {
      nextIdx = curIdx >= 0 ? (curIdx + 1) % list.length : 0
    } else {
      nextIdx = curIdx > 0 ? curIdx - 1 : list.length - 1
    }
    const target = list[nextIdx]
    if (target) {
      syncHighlightedEl(target)
      target.focus?.()
      target.scrollIntoView?.({ block: 'nearest' })
    }
  }

  const handleMenuPointerMove = (event: ReactPointerEvent<HTMLDivElement>) => {
    if (!didPointerActuallyMove(lastPointerRef, event)) return
    const panel = panelRef.current
    if (!panel) return
    const hit =
      event.target instanceof Element
        ? event.target.closest<HTMLButtonElement>('.hs-fb-item')
        : null
    if (hit && !hit.disabled && panel.contains(hit)) {
      syncHighlightedEl(hit)
      const doc = panel.ownerDocument
      if (doc && doc.activeElement && doc.activeElement !== panel && panel.contains(doc.activeElement)) {
        panel.focus?.({ preventScroll: true })
      }
    }
  }

  const handleMenuPointerLeave = () => {
    lastPointerRef.current = null
    syncHighlightedEl(null)
    if (closeOnPointerLeave) {
      onCloseRef.current()
    }
  }

  const resolvedSide = placement?.side ?? side
  const resolvedMaxHeight =
    maxHeight !== undefined
      ? typeof maxHeight === 'number' && placement !== null
        ? Math.min(maxHeight, placement.maxHeight)
        : maxHeight
      : placement !== null
        ? placement.maxHeight
        : undefined
  const menuStyle: CSSProperties = placement
    ? { left: placement.left, top: placement.top, zIndex }
    : { ...HIDDEN, zIndex }

  const list = (
    <OverlayParentContext.Provider value={layerId}>
      <MenuSurface
        ref={panelRef}
        role="menu"
        tabIndex={-1}
        compact={compact}
        footer={footer}
        maxBodyHeight={resolvedMaxHeight}
        origin={placement?.origin}
        data-dsh-portal={portal ? '' : undefined}
        data-menu-managed=""
        data-side={resolvedSide}
        data-align={align}
        data-pop-anim={placement !== null || typeof window === 'undefined' ? 'true' : undefined}
        className="hs-fb-menu"
        style={menuStyle}
        onKeyDown={handleMenuKeyDown}
        onPointerMove={handleMenuPointerMove}
        onPointerLeave={handleMenuPointerLeave}
      >
        {items.map(renderEntry)}
        {children}
      </MenuSurface>
    </OverlayParentContext.Provider>
  )

  return (
    <span ref={anchorRef} className="hs-fb-anchor">
      {cloneElement(anchor, { 'aria-haspopup': 'menu', 'aria-expanded': open })}
      {open && (portal && typeof document !== 'undefined' && Boolean(document.body)
        ? createPortal(list, document.body)
        : list)}
    </span>
  )
}

/** 退化 Modal 直接委托至标准 Modal，消除重复实现，共享 inert 背景锁焦与焦点归还。 */
function FallbackModal(props: ModalProps) {
  return <Modal {...props} />
}

const FALLBACKS: { [K in Name]: ComponentType<never> } = {
  Menu: FallbackMenu as ComponentType<never>,
  MenuItemButton: FallbackMenuItemButton as ComponentType<never>,
  Modal: FallbackModal as ComponentType<never>,
  HoverCard: FallbackHoverCard as ComponentType<never>,
  Tooltip: FallbackTooltip as ComponentType<never>,
  Switch: StandaloneSwitch as ComponentType<never>,
}

