import React, {
  forwardRef,
  useCallback,
  useEffect,
  useId,
  useLayoutEffect,
  useRef,
  useState,
  type ButtonHTMLAttributes,
  type CSSProperties,
  type ReactNode,
  type Ref,
} from 'react'
import { createPortal } from 'react-dom'
import { MenuSurface } from './MenuSurface'
import { readFrameTopClearance } from './anchored-position'
import { isImeComposing } from './host-bridge'
import { InfoIcon } from './icons'
import {
  placeInfoTip,
  type InfoTipAnchorRect,
  type InfoTipBoundsRect,
  type InfoTipPlacement,
  type PlaceInfoTipOptions,
} from './infotip-place'
import { OverlayParentContext, useOverlayLayer } from './overlay-stack'

export {
  placeInfoTip,
  type InfoTipAnchorRect,
  type InfoTipBoundsRect,
  type InfoTipPlacement,
  type PlaceInfoTipOptions,
} from './infotip-place'

export interface InfoTipProps
  extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'content' | 'type' | 'children'> {
  /** 详情说明正文（支持单行短提示、多行文本或自定义节点；为空时不渲染按钮）。 */
  content: ReactNode
  /** 按钮无障碍标签（默认「查看说明」）。 */
  label?: string
  /** 尺寸：sm=24px（适配列表行内操作），md=28px（--dsh-control-sm）。 */
  size?: 'sm' | 'md'
  /** 鼠标悬停展开延迟（毫秒，默认 120ms）。 */
  delayMs?: number
  /** 浮层最大宽度（默认 300px）。 */
  maxWidth?: number
  /** 垂直首选方向（默认 top，贴上方不挡下一行列表）。 */
  side?: 'top' | 'bottom'
  /** 水平首选对齐（默认 end：右缘对齐 ⓘ 从右往左展开贴合左侧文案，按所属容器与视口内壁自动夹紧）。 */
  align?: 'center' | 'start' | 'end'
  /** 点击时是否阻止抢走输入框焦点（如斜杠面板等场景，默认 false）。 */
  preventFocusSteal?: boolean
  /** 是否通过 Portal 挂载到 document.body（默认 true）。 */
  portal?: boolean
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  popClassName?: string
}

function findEnclosingBounds(btn: HTMLElement): InfoTipBoundsRect | null {
  if (typeof btn.closest !== 'function') return null
  const container = btn.closest<HTMLElement>(
    '.hs-msurf, .dsh-modal, .modal-static, .live-dialog, .dsh-card, .spec-box',
  )
  if (!container) return null
  const rect = container.getBoundingClientRect()
  if (typeof rect?.left !== 'number' || typeof rect?.right !== 'number' || rect.right <= rect.left) {
    return null
  }
  return rect
}

function mergeRefs<T>(...refs: Array<Ref<T> | undefined>): (node: T | null) => void {
  return (node) => {
    for (const ref of refs) {
      if (!ref) continue
      if (typeof ref === 'function') ref(node)
      else (ref as { current: T | null }).current = node
    }
  }
}

/**
 * 03 / 06 说明按钮与自适应说明气泡（InfoTip）：
 * - 凡独立 ⓘ 说明按钮均归口本原语（单行短提示与多行详情通用，width: max-content 最宽 300px）；
 * - 三态单向升级（关闭 / 悬停预览 / 点击锁定）：桌面端悬停 120ms 进入临时预览；预览态下点击原地升级为点击锁定而不关闭，仅已锁定时再次点击或经外部点击 / Esc / 滚动关闭；触屏与键盘（Enter / Space）直接锁定并阻断冒泡防误触整行；
 * - 接入统一 overlay-stack：在 Modal 内自动抬升 z-index，在 Popover 内点击气泡正文绝不误关父级 Popover，按 Esc 仅收起当前气泡。
 */
export const InfoTip = forwardRef<HTMLButtonElement, InfoTipProps>(function InfoTip(
  {
    content,
    label = '查看说明',
    size = 'sm',
    delayMs = 120,
    maxWidth = 300,
    side,
    align,
    preventFocusSteal = false,
    portal = true,
    open: controlledOpen,
    defaultOpen = false,
    onOpenChange,
    className,
    popClassName,
    onPointerEnter,
    onPointerLeave,
    onMouseDown,
    onClick,
    onKeyDown,
    ...rest
  },
  forwardedRef,
) {
  const tipId = useId()
  const btnRef = useRef<HTMLButtonElement | null>(null)
  const popRef = useRef<HTMLDivElement | null>(null)
  const timerRef = useRef<ReturnType<typeof setTimeout> | undefined>(undefined)
  // 仅由悬停延迟触发的临时预览为 true；点击/键盘打开、预览态点击锁定、defaultOpen 或外部受控展开均为 false
  const hoverPreviewRef = useRef(false)

  const [uncontrolledOpen, setUncontrolledOpen] = useState(defaultOpen)
  const isControlled = controlledOpen !== undefined
  const isOpen = isControlled ? controlledOpen : uncontrolledOpen
  const [place, setPlace] = useState<InfoTipPlacement | null>(null)

  const computePlace = useCallback(
    (bubble?: { width: number; height: number }): InfoTipPlacement | null => {
      const btn = btnRef.current
      if (!btn || typeof window === 'undefined') return null
      const rect = btn.getBoundingClientRect()
      const vv = window.visualViewport
      return placeInfoTip(
        rect,
        { width: vv?.width ?? window.innerWidth, height: window.innerHeight },
        {
          maxWidth,
          side,
          align,
          topClearance: readFrameTopClearance(12),
          containerBounds: findEnclosingBounds(btn),
          bubbleWidth: bubble?.width,
          bubbleHeight: bubble?.height,
        },
      )
    },
    [maxWidth, side, align],
  )

  const syncPlace = useCallback(() => {
    const pop = popRef.current
    const bubble = pop ? { width: pop.offsetWidth, height: pop.offsetHeight } : undefined
    const next = computePlace(bubble)
    if (!next) return
    setPlace((prev) =>
      prev
      && prev.left === next.left
      && prev.maxWidth === next.maxWidth
      && prev.top === next.top
      && prev.bottom === next.bottom
      && prev.side === next.side
      && prev.align === next.align
      && prev.origin === next.origin
        ? prev
        : next,
    )
  }, [computePlace])

  const closeTip = useCallback(() => {
    clearTimeout(timerRef.current)
    hoverPreviewRef.current = false
    if (!isControlled) setUncontrolledOpen(false)
    onOpenChange?.(false)
  }, [isControlled, onOpenChange])

  const openTip = useCallback(
    (pinned: boolean) => {
      clearTimeout(timerRef.current)
      hoverPreviewRef.current = !pinned
      const nextPlace = computePlace()
      if (nextPlace) setPlace(nextPlace)
      if (!isControlled) setUncontrolledOpen(true)
      onOpenChange?.(true)
    },
    [computePlace, isControlled, onOpenChange],
  )

  const activateTrigger = useCallback(() => {
    clearTimeout(timerRef.current)
    if (!isOpen) {
      openTip(true)
      return
    }
    if (hoverPreviewRef.current) {
      // 悬停预览态下点击/按键：原地升级为锁定态，保持 DOM 不卸载且不重播入场动画
      hoverPreviewRef.current = false
      return
    }
    closeTip()
  }, [closeTip, isOpen, openTip])

  const { layerId, zIndex } = useOverlayLayer({
    open: isOpen,
    tier: 'infotip',
    containsNode: (node) =>
      Boolean(btnRef.current?.contains(node) || popRef.current?.contains(node)),
    onEscape: () => {
      closeTip()
    },
    onPointerDownOutside: () => {
      closeTip()
    },
  })

  useEffect(() => () => clearTimeout(timerRef.current), [])

  const useClientLayoutEffect = typeof document !== 'undefined' ? useLayoutEffect : useEffect
  useClientLayoutEffect(() => {
    if (!isOpen) return undefined
    syncPlace()
    if (typeof window === 'undefined') return undefined
    window.addEventListener('resize', syncPlace)
    const pop = popRef.current
    let observer: ResizeObserver | null = null
    if (typeof ResizeObserver !== 'undefined' && pop) {
      observer = new ResizeObserver(syncPlace)
      observer.observe(pop)
    }
    return () => {
      observer?.disconnect()
      window.removeEventListener('resize', syncPlace)
    }
  }, [isOpen, syncPlace])

  useEffect(() => {
    if (!isOpen) {
      hoverPreviewRef.current = false
      clearTimeout(timerRef.current)
      setPlace((prev) => (prev === null ? prev : null))
      return undefined
    }

    if (typeof window === 'undefined') return undefined

    const onScroll = (event: Event) => {
      const target = event.target
      if (target instanceof Node && popRef.current?.contains(target)) return
      closeTip()
    }

    window.addEventListener('blur', closeTip)
    window.addEventListener('scroll', onScroll, true)

    return () => {
      window.removeEventListener('blur', closeTip)
      window.removeEventListener('scroll', onScroll, true)
    }
  }, [isOpen, closeTip])

  if (content === undefined || content === null || content === '') {
    return null
  }

  const fallbackSide = side ?? 'top'
  const fallbackAlign = align ?? 'end'
  const resolvedPlace: InfoTipPlacement = place ?? {
    left: 0,
    maxWidth,
    ...(fallbackSide === 'top' ? { bottom: 0 } : { top: 0 }),
    side: fallbackSide,
    align: fallbackAlign,
    origin: `${fallbackAlign === 'start' ? 'left' : fallbackAlign === 'end' ? 'right' : 'center'} ${fallbackSide === 'top' ? 'bottom' : 'top'}`,
  }
  const popStyle: CSSProperties = {
    zIndex,
    left: resolvedPlace.left,
    maxWidth: resolvedPlace.maxWidth,
    top: resolvedPlace.top,
    bottom: resolvedPlace.bottom,
    ...(typeof window !== 'undefined' && place === null ? { visibility: 'hidden' } : {}),
  }

  const popNode = isOpen ? (
    <OverlayParentContext.Provider value={layerId}>
      <MenuSurface
        ref={popRef}
        compact
        material="translucent"
        id={tipId}
        role="tooltip"
        data-dsh-portal=""
        origin={resolvedPlace.origin}
        data-side={resolvedPlace.side}
        data-align={resolvedPlace.align}
        data-pop-anim={place !== null || typeof window === 'undefined' ? 'true' : undefined}
        className={`dsh-infotip-pop${popClassName ? ` ${popClassName}` : ''}`}
        style={popStyle}
        onPointerLeave={(event) => {
          if (!hoverPreviewRef.current) return
          const related = event.relatedTarget
          if (related instanceof Node && btnRef.current?.contains(related)) return
          closeTip()
        }}
      >
        <div className="dsh-infotip-body">{content}</div>
      </MenuSurface>
    </OverlayParentContext.Provider>
  ) : null

  const canPortal = portal && typeof document !== 'undefined' && Boolean(document.body)

  return (
    <>
      <button
        {...rest}
        ref={mergeRefs(btnRef, forwardedRef)}
        type="button"
        aria-label={label}
        aria-expanded={isOpen}
        aria-describedby={isOpen ? tipId : undefined}
        className={`dsh-infotip-btn${size === 'md' ? ' dsh-infotip-btn-md' : ''}${className ? ` ${className}` : ''}`}
        onPointerEnter={(event) => {
          onPointerEnter?.(event)
          if (event.pointerType === 'touch') return
          clearTimeout(timerRef.current)
          if (isOpen) return
          const openHover = () => {
            if (btnRef.current && btnRef.current.isConnected === false) return
            openTip(false)
          }
          if (delayMs <= 0) openHover()
          else timerRef.current = setTimeout(openHover, delayMs)
        }}
        onPointerLeave={(event) => {
          onPointerLeave?.(event)
          clearTimeout(timerRef.current)
          if (!isOpen || !hoverPreviewRef.current) return
          const related = event.relatedTarget
          if (related instanceof Node && popRef.current?.contains(related)) return
          closeTip()
        }}
        onMouseDown={(event) => {
          if (preventFocusSteal) {
            event.preventDefault()
            event.stopPropagation?.()
          }
          onMouseDown?.(event)
        }}
        onClick={(event) => {
          event.stopPropagation?.()
          onClick?.(event)
          if (event.defaultPrevented) return
          activateTrigger()
        }}
        onKeyDown={(event) => {
          onKeyDown?.(event)
          if (event.defaultPrevented || isImeComposing(event)) return
          if (event.key === 'Enter' || event.key === ' ') {
            event.preventDefault()
            event.stopPropagation?.()
            activateTrigger()
          }
        }}
      >
        <InfoIcon size={14} inline={false} />
      </button>
      {popNode !== null
        ? canPortal
          ? createPortal(popNode, document.body)
          : popNode
        : null}
    </>
  )
})

