import { beginGlobalDrag } from './host-bridge'

export interface AttachScrollAreaOptions {
  /** 流式输出跟随贴底：距底 <= 40px 时内容增长自动滚底，用户主动上滚触发 150ms 冷却锁。 */
  followBottom?: boolean
  /** 显示悬浮细滑块的最小内容高度倍率（默认 2 即超过 2 屏；下拉菜单传 1.05）。 */
  thumbThreshold?: number
  /** 时间源注入（便于单测精确验证 150ms 冷却锁）。 */
  now?: () => number
}

const LONG_LIST_RATIO = 2
const THUMB_PAD = 6
const FOLLOW_BOTTOM_THRESHOLD = 40
const USER_SCROLL_COOLDOWN_MS = 150
const SCROLL_ACTIVE_FLASH_MS = 900

function setBoolAttr(el: Element, name: string, on: boolean): void {
  if (on) el.setAttribute(name, '')
  else el.removeAttribute(name)
}

export interface AttachedScrollAreaBinding {
  sync: () => void
  dispose: () => void
}

/**
 * 05 ScrollArea 纯 DOM 挂载内核（零外部依赖）：
 * - 动态计算 scrollTop 与可滚高度，切换视口 data-fade-top / data-fade-bottom 驱动 7 段幂律边缘渐隐；
 * - 内容超过阈值时在外框启用悬浮细滑块 .dsh-scroll-thumb（aria-hidden，支持指针拖拽并接入 beginGlobalDrag 防吞指针盾）；
 * - 常驻轻量 MutationObserver：列表筛减、分组折叠跨越阈值时即时刷新滑块与渐隐；
 * - 可选 followBottom 流式自动贴底（距底 <= 40px 自动跟随，用户主动上滚 150ms 冷却防抢滚动条）。
 */
export function attachScrollAreaWithSync(
  viewport: HTMLElement,
  options?: AttachScrollAreaOptions,
): AttachedScrollAreaBinding {
  const frame = viewport.parentElement
  const thumb = frame?.querySelector<HTMLElement>('.dsh-scroll-thumb') ?? null
  const followBottom = Boolean(options?.followBottom)
  const thumbThreshold = options?.thumbThreshold ?? LONG_LIST_RATIO
  const now = options?.now ?? (() => Date.now())

  const win = viewport.ownerDocument?.defaultView
  const setTimer =
    typeof win?.setTimeout === 'function' ? win.setTimeout.bind(win) : setTimeout
  const clearTimer =
    typeof win?.clearTimeout === 'function' ? win.clearTimeout.bind(win) : clearTimeout

  let disposed = false
  let hideTimer: ReturnType<typeof setTimeout> | null = null
  let drag: { y: number; scroll: number; releaseShield: () => void } | null = null
  let lastScrollTop = viewport.scrollTop || 0
  let lastScrollHeight = viewport.scrollHeight || 0
  let nearBottom =
    lastScrollHeight - (viewport.clientHeight || 0) - lastScrollTop <= FOLLOW_BOTTOM_THRESHOLD
  let cooldownUntil = 0
  let programmaticScroll = false

  const metrics = () => {
    const clientH = viewport.clientHeight || 0
    const scrollH = viewport.scrollHeight || 0
    const track = Math.max(0, clientH - THUMB_PAD * 2)
    const rawH = scrollH > 0 ? Math.max(24, (track * clientH) / scrollH) : 24
    const h = track > 0 ? Math.min(track, rawH) : 0
    return { clientH, scrollH, track, h, maxScroll: Math.max(0, scrollH - clientH) }
  }

  const sync = () => {
    if (disposed) return
    const { clientH, scrollH, track, h, maxScroll } = metrics()
    const topPos = viewport.scrollTop || 0
    const hasTop = topPos > 2
    const hasBot = clientH > 0 && topPos + clientH < scrollH - 2
    setBoolAttr(viewport, 'data-fade-top', hasTop)
    setBoolAttr(viewport, 'data-fade-bottom', hasBot)

    if (!thumb) return
    const isLong = clientH > 0 && track > 0 && scrollH > clientH * thumbThreshold
    thumb.hidden = !isLong
    if (!isLong) {
      if (!drag) frame?.removeAttribute('data-scroll-active')
      return
    }
    const offsetTop = viewport.offsetTop || 0
    const thumbTop =
      offsetTop + THUMB_PAD + Math.max(0, track - h) * (maxScroll > 0 ? topPos / maxScroll : 0)
    thumb.style.height = `${h}px`
    thumb.style.transform = `translateY(${thumbTop}px)`
  }

  const scheduleHideActive = () => {
    if (!frame) return
    if (hideTimer !== null) {
      clearTimer(hideTimer)
      hideTimer = null
    }
    if (!drag && !disposed) {
      hideTimer = setTimer(() => {
        hideTimer = null
        if (!disposed && !drag) {
          frame.removeAttribute('data-scroll-active')
        }
      }, SCROLL_ACTIVE_FLASH_MS)
    }
  }

  const maybeStickToBottom = () => {
    if (!followBottom) return
    const curScrollH = viewport.scrollHeight || 0
    const curClientH = viewport.clientHeight || 0
    const curTop = viewport.scrollTop || 0
    if (curScrollH <= lastScrollHeight) {
      lastScrollHeight = curScrollH
      nearBottom = curScrollH - curClientH - curTop <= FOLLOW_BOTTOM_THRESHOLD
      return
    }
    const prevDistance = lastScrollHeight - curClientH - curTop
    const shouldStick =
      (nearBottom || prevDistance <= FOLLOW_BOTTOM_THRESHOLD) && now() >= cooldownUntil
    lastScrollHeight = curScrollH
    if (shouldStick) {
      programmaticScroll = true
      viewport.scrollTop = Math.max(0, curScrollH - curClientH)
      lastScrollTop = viewport.scrollTop
      nearBottom = true
      programmaticScroll = false
    } else {
      nearBottom = curScrollH - curClientH - curTop <= FOLLOW_BOTTOM_THRESHOLD
    }
  }

  const onScroll = () => {
    const curTop = viewport.scrollTop || 0
    const curScrollH = viewport.scrollHeight || 0
    const curClientH = viewport.clientHeight || 0

    if (!programmaticScroll && curTop < lastScrollTop - 1) {
      cooldownUntil = now() + USER_SCROLL_COOLDOWN_MS
    }
    lastScrollTop = curTop
    lastScrollHeight = curScrollH
    nearBottom = curScrollH - curClientH - curTop <= FOLLOW_BOTTOM_THRESHOLD

    sync()
    if (frame) {
      frame.setAttribute('data-scroll-active', '')
      scheduleHideActive()
    }
  }

  const onWheel = (event: Event) => {
    const deltaY = (event as WheelEvent).deltaY
    if (typeof deltaY === 'number' && deltaY < 0) {
      cooldownUntil = now() + USER_SCROLL_COOLDOWN_MS
    }
  }

  const endDrag = (event?: Event) => {
    if (drag) {
      event?.preventDefault?.()
      event?.stopPropagation?.()
      drag.releaseShield()
      drag = null
      thumb?.removeAttribute('data-dragging')
      scheduleHideActive()
      return
    }
    thumb?.removeAttribute('data-dragging')
  }

  const onThumbDown = (event: PointerEvent) => {
    event.preventDefault?.()
    event.stopPropagation?.()
    if (!thumb || disposed) return
    endDrag()
    thumb.setPointerCapture?.(event.pointerId)
    thumb.setAttribute('data-dragging', '')
    frame?.setAttribute('data-scroll-active', '')
    if (hideTimer !== null) {
      clearTimer(hideTimer)
      hideTimer = null
    }
    const releaseShield = beginGlobalDrag(viewport.ownerDocument as Document | undefined)
    drag = { y: event.clientY, scroll: viewport.scrollTop || 0, releaseShield }
  }

  const onThumbMove = (event: PointerEvent) => {
    if (!drag || disposed) return
    event.preventDefault?.()
    event.stopPropagation?.()
    const { track, h, maxScroll } = metrics()
    const next = drag.scroll + ((event.clientY - drag.y) * maxScroll) / Math.max(1, track - h)
    viewport.scrollTop = Math.min(maxScroll, Math.max(0, next))
    sync()
  }

  const swallowClick = (event: Event) => {
    event.preventDefault?.()
    event.stopPropagation?.()
  }

  viewport.addEventListener('scroll', onScroll, { passive: true })
  viewport.addEventListener('wheel', onWheel, { passive: true })
  thumb?.addEventListener('pointerdown', onThumbDown)
  thumb?.addEventListener('pointermove', onThumbMove)
  thumb?.addEventListener('pointerup', endDrag)
  thumb?.addEventListener('pointercancel', endDrag)
  thumb?.addEventListener('lostpointercapture', endDrag)
  thumb?.addEventListener('click', swallowClick)

  const ResizeCtor =
    (win as unknown as { ResizeObserver?: typeof ResizeObserver } | null)?.ResizeObserver
    ?? globalThis.ResizeObserver
  const ro = ResizeCtor
    ? new ResizeCtor(() => {
        maybeStickToBottom()
        sync()
      })
    : null
  ro?.observe(viewport)

  const MutationCtor =
    (win as unknown as { MutationObserver?: typeof MutationObserver } | null)?.MutationObserver
    ?? globalThis.MutationObserver
  const mo = MutationCtor
    ? new MutationCtor(() => {
        maybeStickToBottom()
        sync()
      })
    : null
  mo?.observe(viewport, {
    childList: true,
    subtree: true,
    ...(followBottom ? { characterData: true } : {}),
  })

  sync()

  const dispose = () => {
    if (disposed) return
    disposed = true
    if (drag) {
      drag.releaseShield()
      drag = null
    }
    thumb?.removeAttribute('data-dragging')
    frame?.removeAttribute('data-scroll-active')
    if (hideTimer !== null) {
      clearTimer(hideTimer)
      hideTimer = null
    }
    ro?.disconnect()
    mo?.disconnect()
    viewport.removeEventListener('scroll', onScroll)
    viewport.removeEventListener('wheel', onWheel)
    thumb?.removeEventListener('pointerdown', onThumbDown)
    thumb?.removeEventListener('pointermove', onThumbMove)
    thumb?.removeEventListener('pointerup', endDrag)
    thumb?.removeEventListener('pointercancel', endDrag)
    thumb?.removeEventListener('lostpointercapture', endDrag)
    thumb?.removeEventListener('click', swallowClick)
  }

  return { sync, dispose }
}

/**
 * 05 ScrollArea 命令式挂载器（返回幂等清理函数）。
 */
export function attachScrollArea(
  viewport: HTMLElement,
  options?: AttachScrollAreaOptions,
): () => void {
  return attachScrollAreaWithSync(viewport, options).dispose
}
