import {
  useEffect,
  useRef,
  type KeyboardEvent as ReactKeyboardEvent,
  type RefObject,
} from 'react'
import { mountSlidingIndicator } from './dom-primitives'
import { isImeComposing } from './host-bridge'

export interface SlidingIndicatorOptions {
  itemSelector?: string
  indicatorClass?: string
}

export interface RovingKeyDownOptions {
  itemSelector?: string
  /** 方向键响应轴：默认对水平 role="tablist" 取 'horizontal'（放行 ↑/↓），对 radiogroup 等取 'both'。 */
  orientation?: 'horizontal' | 'vertical' | 'both'
  /** 漫游激活策略：默认 'automatic' 焦点移动即选中；'manual' 仅移动焦点，由 Enter / Space 激活。 */
  activationMode?: 'automatic' | 'manual'
}

const DEFAULT_ITEM_SELECTOR = '[role="tab"], button'
const DEFAULT_INDICATOR_CLASS = 'dsh-seg-ind'

/**
 * 08.2 滑动选中指示块（Segmented / UnderlineTabs / Popover 分类条通用）：
 * - 注入独立 aria-hidden 指示节点并挂载 data-ind 属性接管选中底；
 * - 首次挂载、从隐藏零宽态首次恢复、动态增删子项及 ResizeObserver（含容器与各子项尺寸变化）瞬时到位；
 * - aria-selected / aria-pressed / aria-current="page" 在有效项间切换时以 --dsh-dur-expand + --dsh-ease-out 驱动 transform 与 width 平滑滑动；
 * - 返回幂等 dispose() 断开观察器并移除节点。
 */
export function attachSlidingIndicator(
  container: HTMLElement,
  options?: SlidingIndicatorOptions,
): () => void {
  const handle = mountSlidingIndicator(container, {
    itemSelector: options?.itemSelector ?? DEFAULT_ITEM_SELECTOR,
    indicatorClass: options?.indicatorClass ?? DEFAULT_INDICATOR_CLASS,
  })
  return () => handle.destroy()
}

function isIndicatorOptions(value: unknown): value is SlidingIndicatorOptions {
  if (typeof value !== 'object' || value === null) return false
  return 'itemSelector' in value || 'indicatorClass' in value
}

/**
 * React Hook 封装：在容器 ref 上自动绑定与清理滑动选中指示块。
 * 兼容条件挂载（如 Popover open: false -> true）：节点未变时保持平滑过渡，节点挂载/卸载时自动绑定与回收。
 */
export function useSlidingIndicator(
  ref: RefObject<HTMLElement | null>,
  options?: SlidingIndicatorOptions,
): void
export function useSlidingIndicator(
  ref: RefObject<HTMLElement | null>,
  dep?: unknown,
  options?: SlidingIndicatorOptions,
): void
export function useSlidingIndicator(
  ref: RefObject<HTMLElement | null>,
  depOrOptions?: unknown,
  maybeOptions?: SlidingIndicatorOptions,
): void {
  const hasDep =
    maybeOptions !== undefined
    || (depOrOptions !== undefined && !isIndicatorOptions(depOrOptions))
  const dep = hasDep ? depOrOptions : undefined
  const resolvedOptions =
    maybeOptions !== undefined
      ? maybeOptions
      : isIndicatorOptions(depOrOptions)
        ? depOrOptions
        : undefined
  const itemSelector = resolvedOptions?.itemSelector
  const indicatorClass = resolvedOptions?.indicatorClass

  const bindingRef = useRef<{
    el: HTMLElement | null
    itemSelector?: string
    indicatorClass?: string
    dispose: (() => void) | null
  }>({
    el: null,
    itemSelector: undefined,
    indicatorClass: undefined,
    dispose: null,
  })

  useEffect(() => {
    const el = ref.current
    const cur = bindingRef.current
    if (
      cur.el === el
      && cur.itemSelector === itemSelector
      && cur.indicatorClass === indicatorClass
    ) {
      return undefined
    }
    cur.dispose?.()
    if (!el) {
      bindingRef.current = { el: null, itemSelector, indicatorClass, dispose: null }
      return undefined
    }
    const dispose = attachSlidingIndicator(el, { itemSelector, indicatorClass })
    bindingRef.current = { el, itemSelector, indicatorClass, dispose }
    return undefined
  }, [ref, itemSelector, indicatorClass, dep])

  useEffect(
    () => () => {
      bindingRef.current.dispose?.()
      bindingRef.current = {
        el: null,
        itemSelector: undefined,
        indicatorClass: undefined,
        dispose: null,
      }
    },
    [],
  )
}

const HORIZONTAL_KEYS = new Set(['ArrowRight', 'ArrowLeft', 'Home', 'End'])
const VERTICAL_KEYS = new Set(['ArrowDown', 'ArrowUp', 'Home', 'End'])
const ALL_ROVING_KEYS = new Set([
  'ArrowRight',
  'ArrowDown',
  'ArrowLeft',
  'ArrowUp',
  'Home',
  'End',
])

/**
 * 08.1 Roving Tabindex 方向键漫游（← / → / ↑ / ↓ / Home / End）：
 * - 对水平 role="tablist" 默认仅拦截 ← / → / Home / End，不劫持 ↑ / ↓ 页面滚动或下拉导航；
 * - 对 role="radiogroup" 等默认保留四向漫游；
 * - 自动跳过禁用与隐藏项，同步 tabindex="0/-1"，支持 automatic（默认）与 manual 激活模式。
 */
export function handleRovingKeyDown(
  event: ReactKeyboardEvent<HTMLElement>,
  itemSelectorOrOptions: string | RovingKeyDownOptions = '[role="tab"], [role="radio"], button',
): void {
  if (isImeComposing(event)) return

  const opts: RovingKeyDownOptions =
    typeof itemSelectorOrOptions === 'string'
      ? { itemSelector: itemSelectorOrOptions }
      : itemSelectorOrOptions
  const itemSelector = opts.itemSelector ?? '[role="tab"], [role="radio"], button'
  const activationMode = opts.activationMode ?? 'automatic'

  const container = event.currentTarget
  if (!container) return

  const resolvedOrientation =
    opts.orientation
    ?? (container.getAttribute?.('role') === 'tablist'
      ? container.getAttribute?.('aria-orientation') === 'vertical'
        ? 'vertical'
        : 'horizontal'
      : 'both')

  const allowedKeys =
    resolvedOrientation === 'horizontal'
      ? HORIZONTAL_KEYS
      : resolvedOrientation === 'vertical'
        ? VERTICAL_KEYS
        : ALL_ROVING_KEYS

  if (!allowedKeys.has(event.key)) return

  const allItems = Array.from(container.querySelectorAll<HTMLElement>(itemSelector))
  const enabledItems = allItems.filter((el) => {
    if ((el as HTMLButtonElement).disabled) return false
    if (el.getAttribute('aria-disabled') === 'true') return false
    if (el.hidden || el.getAttribute('aria-hidden') === 'true') return false
    if (el.style?.display === 'none') return false
    return true
  })

  if (enabledItems.length === 0) return

  const doc = container.ownerDocument
  const activeEl = (doc?.activeElement ?? event.target) as Node | null
  let currentIndex = enabledItems.findIndex(
    (el) =>
      el === activeEl
      || (activeEl !== null && typeof el.contains === 'function' && el.contains(activeEl)),
  )
  if (currentIndex < 0) {
    currentIndex = enabledItems.findIndex(
      (el) =>
        el.getAttribute('aria-selected') === 'true'
        || el.getAttribute('aria-checked') === 'true'
        || el.getAttribute('tabindex') === '0',
    )
  }
  if (currentIndex < 0) currentIndex = 0

  event.preventDefault()

  let nextIndex = currentIndex
  if (event.key === 'ArrowRight' || event.key === 'ArrowDown') {
    nextIndex = (currentIndex + 1) % enabledItems.length
  } else if (event.key === 'ArrowLeft' || event.key === 'ArrowUp') {
    nextIndex = (currentIndex - 1 + enabledItems.length) % enabledItems.length
  } else if (event.key === 'Home') {
    nextIndex = 0
  } else if (event.key === 'End') {
    nextIndex = enabledItems.length - 1
  }

  const nextEl = enabledItems[nextIndex]
  if (!nextEl) return

  for (const item of allItems) {
    item.setAttribute('tabindex', item === nextEl ? '0' : '-1')
  }
  nextEl.focus?.()
  if (activationMode === 'automatic') {
    nextEl.click?.()
  }
}

/**
 * 判断列表项上的 pointermove 是否来自真实指针移动（排除键盘滚动列表时静止鼠标伪触发）：
 */
export function didPointerActuallyMove(
  lastPosRef: { current: { x: number; y: number } | null },
  event: { clientX?: number; clientY?: number; pointerType?: string },
): boolean {
  if (event.pointerType === 'touch') return false
  const x = typeof event.clientX === 'number' ? event.clientX : 0
  const y = typeof event.clientY === 'number' ? event.clientY : 0
  const prev = lastPosRef.current
  if (prev !== null && prev.x === x && prev.y === y) {
    return false
  }
  lastPosRef.current = { x, y }
  return true
}
