/** @jsxImportSource react */
import React, {
  forwardRef,
  useEffect,
  useId,
  useLayoutEffect,
  useRef,
  type CSSProperties,
  type HTMLAttributes,
  type ReactNode,
} from 'react'
import { createPortal } from 'react-dom'
import { ScrollArea } from './ScrollArea'

/**
 * 统一浮层外壳：对齐宿主官方 ui-primitives 的 MenuSurface（标准 16px --dsw-radius-lg，compact 档 12px --dsw-radius-md）。
 *
 * - translucent（默认，临时菜单/复合浮层）：接入全系唯一待办栏共享毛玻璃（--dsh-menu-surface-fill 浅 80% / 深 66% + blur(8px) saturate(1.3) + --dsh-glass-shadow），
 *   内部 .hs-msurf-material 隔离绘制磨砂，macOS 下通过 CSS anchor 在 body 末尾挂一块不透明 backing 防止透出桌面；
 * - solid（常驻信息面板）：把菜单主题色叠在不透明基底上，滚动聊天区时无需逐帧重采样背后的文字和壁纸。
 * - 支持同心菜单项（16-4=12px / 12-4=8px）、12px 两端留白分割线、可选底部固定栏 .hs-msurf-footer、方位感知缩放与系统减透实底退化。
 */
export type MenuSurfaceProps = HTMLAttributes<HTMLDivElement> & {
  /** 紧凑档圆角（12px，对齐 --dsw-radius-md，内部同心项自动缩为 8px）。 */
  compact?: boolean
  /** 常驻信息面板使用不依赖滚动背景的实底；临时菜单默认保留待办栏透影磨砂；optical 为零模糊光学玻璃。 */
  material?: 'translucent' | 'solid' | 'optical'
  /** 底部常驻操作区（自动带两端留白顶部分割线与 sticky 吸底）。 */
  footer?: ReactNode
  /** 主体列表区最大高度（传入后自动包裹于内缩 ScrollArea，防止滚动条穿出圆角面板）。 */
  maxBodyHeight?: number | string
  /** 顺应触发器方位的展开缩放原点（例如 'top left' | 'top right' | 'bottom left' | 'bottom right'）。 */
  origin?: CSSProperties['transformOrigin']
  style?: CSSProperties
  [data: `data-${string}`]: string | undefined
}

export const MenuSurface = forwardRef<HTMLDivElement, MenuSurfaceProps>(function MenuSurface(
  {
    compact = false,
    material = 'translucent',
    footer,
    maxBodyHeight,
    origin,
    className,
    style,
    children,
    ...rest
  },
  ref,
) {
  const id = useId()
  const surfaceRef = useRef<HTMLDivElement | null>(null)
  const backingRef = useRef<HTMLDivElement>(null)
  const setSurfaceRef = (el: HTMLDivElement | null) => {
    surfaceRef.current = el
    if (typeof ref === 'function') ref(el)
    else if (ref) ref.current = el
  }
  const useClientLayoutEffect = typeof document !== 'undefined' ? useLayoutEffect : useEffect
  useClientLayoutEffect(() => {
    const backingEl = backingRef.current
    if (backingEl === null || typeof document === 'undefined') return
    const overlay = surfaceRef.current?.closest?.('.dsh-modal-overlay, .live-overlay') ?? null
    if (overlay) {
      overlay.insertBefore(backingEl, overlay.firstChild)
    } else if (document.body) {
      document.body.appendChild(backingEl)
    }
  }, [material])
  const anchor = {
    '--dsh-menu-anchor': `--dsh-menu-${id.replaceAll(':', '')}`,
    ...(origin !== undefined ? { '--dsh-pop-origin': origin } : {}),
  } as CSSProperties
  const size = compact ? ' hs-msurf-compact' : ''
  const canPortal = material === 'translucent' && typeof document !== 'undefined' && Boolean(document.body)
  const popAnim = rest['data-pop-anim']
  const dataSide = rest['data-side']
  const dataAlign = rest['data-align']
  return (
    <>
      <div
        {...rest}
        ref={setSurfaceRef}
        data-menu-material={material}
        className={`hs-msurf${size}${className ? ` ${className}` : ''}`}
        style={{ ...style, ...anchor }}
      >
        {material === 'translucent' && <div aria-hidden="true" className="hs-msurf-material" />}
        {maxBodyHeight !== undefined ? (
          <ScrollArea
            maxHeight={maxBodyHeight}
            thumbThreshold={1.05}
            className="hs-msurf-scroll"
            viewportClassName="hs-msurf-scroll-body"
          >
            {children}
          </ScrollArea>
        ) : (
          children
        )}
        {footer !== undefined && <div className="hs-msurf-footer">{footer}</div>}
      </div>
      {canPortal && createPortal(
        <div
          ref={backingRef}
          aria-hidden="true"
          data-menu-backing=""
          data-dsh-portal=""
          data-side={dataSide}
          data-align={dataAlign}
          data-pop-anim={popAnim}
          className={`hs-msurf-backing${size}`}
          style={{ ...anchor, visibility: style?.visibility }}
        />,
        document.body,
      )}
    </>
  )
})

