import React, {
  createContext,
  forwardRef,
  useContext,
  useEffect,
  useId,
  useRef,
  useState,
  type CSSProperties,
  type HTMLAttributes,
  type KeyboardEvent as ReactKeyboardEvent,
  type ReactNode,
  type Ref,
  type RefObject,
} from 'react'
import { createPortal } from 'react-dom'
import { InfoTip } from './InfoTip'
import { MenuSurface } from './MenuSurface'
import { ScrollArea } from './ScrollArea'
import { useAnchoredPlacement } from './anchored-position'
import { isImeComposing } from './host-bridge'
import { ChevronDownIcon, CloseIcon, SearchIcon, StarIcon } from './icons'
import { didPointerActuallyMove, handleRovingKeyDown, useSlidingIndicator } from './motion'
import { OverlayParentContext, useOverlayLayer } from './overlay-stack'

const PopoverModeContext = createContext<{ combobox: boolean }>({ combobox: false })

export interface PopoverCategory {
  id: string
  label: ReactNode
  disabled?: boolean
}

export interface PopoverProps extends Omit<HTMLAttributes<HTMLDivElement>, 'title'> {
  /** 是否打开；内联展示时默认 true，锚定弹层时传受控布尔值。 */
  open?: boolean
  onClose?: () => void
  /** 可选触发器引用：传入后通过 useAnchoredPlacement 自动锚定定位与视口边缘翻转。 */
  anchorRef?: RefObject<HTMLElement | null>
  side?: 'bottom' | 'top'
  align?: 'start' | 'end'
  gap?: number
  /** 是否通过 createPortal 挂到 document.body（传入 anchorRef 时默认 true，内联展示默认 false）。 */
  portal?: boolean
  material?: 'translucent' | 'solid'
  origin?: CSSProperties['transformOrigin']

  /** 顶栏无框搜索框（严守 1-Border Rule：浮层内不重复画胶囊边框，底部分割线两端缩进 8px）。 */
  searchable?: boolean
  searchValue?: string
  defaultSearchValue?: string
  onSearchChange?: (value: string) => void
  onSearchEnter?: (value: string) => void
  searchPlaceholder?: string
  searchAriaLabel?: string
  clearSearchLabel?: string
  autoFocusSearch?: boolean

  /** 顶栏滑动胶囊分类筛选条（复用 useSlidingIndicator + handleRovingKeyDown）。 */
  categories?: readonly PopoverCategory[]
  activeCategory?: string
  defaultCategory?: string
  onCategoryChange?: (categoryId: string) => void
  categoryAriaLabel?: string
  /** 分类条右侧附加动作槽（例如固定图钉按钮）。 */
  headerExtra?: ReactNode

  /** ScrollArea 列表区最大高度（默认 280px；传 undefined 不限制）。 */
  maxBodyHeight?: number | string
  /** 底部快捷键提示或辅助底栏。 */
  footer?: ReactNode
  style?: CSSProperties
  children?: ReactNode
  [data: `data-${string}`]: string | undefined
}

function mergeRefs<T>(...refs: Array<Ref<T> | undefined>): (node: T | null) => void {
  return (node) => {
    for (const r of refs) {
      if (!r) continue
      if (typeof r === 'function') r(node)
      else (r as { current: T | null }).current = node
    }
  }
}

const HIDDEN_POS: CSSProperties = { left: 0, top: 0, visibility: 'hidden' }

/**
 * 复合弹出面板 Popover（README 06.2）：
 * - 基于 MenuSurface 构建：外框 16px (--dsw-radius-lg) − 内距 6px = 内部行 10px 严格同心；
 * - 可选无框搜索顶栏（内置 WAI-ARIA Combobox ↑/↓ 列表游标直选与 isImeComposing 选词守卫）；
 * - 可选滑动胶囊分类条（支持 open: false -> true 动态挂载自愈与水平漫游焦点）；
 * - 主体列表包裹于 ScrollArea（thumbThreshold=1.05 边缘渐隐 + 外圈细滑块）；
 * - 接入统一 overlay-stack：自动高于父级 Modal，内嵌 InfoTip 气泡点击不误关面板。
 */
export const Popover = forwardRef<HTMLDivElement, PopoverProps>(function Popover(
  {
    open = true,
    onClose,
    anchorRef,
    side = 'bottom',
    align = 'start',
    gap = 6,
    portal,
    material = 'translucent',
    origin,
    searchable,
    searchValue,
    defaultSearchValue = '',
    onSearchChange,
    onSearchEnter,
    searchPlaceholder = '搜索…',
    searchAriaLabel = '搜索列表',
    clearSearchLabel = '清空搜索',
    autoFocusSearch = false,
    categories,
    activeCategory,
    defaultCategory,
    onCategoryChange,
    categoryAriaLabel = '分类筛选',
    headerExtra,
    maxBodyHeight = 280,
    footer,
    className,
    style,
    children,
    ...rest
  },
  forwardedRef,
) {
  const rawId = useId()
  const listboxId = `dsh-pop-list-${rawId.replaceAll(':', '')}`
  const panelRef = useRef<HTMLDivElement>(null)
  const searchInputRef = useRef<HTMLInputElement>(null)
  const tabsRef = useRef<HTMLDivElement>(null)
  const bodyRef = useRef<HTMLDivElement>(null)
  const lastPointerRef = useRef<{ x: number; y: number } | null>(null)

  const [uncontrolledSearch, setUncontrolledSearch] = useState(defaultSearchValue)
  const resolvedSearch = searchValue !== undefined ? searchValue : uncontrolledSearch
  const showSearch =
    Boolean(searchable)
    || searchValue !== undefined
    || onSearchChange !== undefined

  const [uncontrolledCat, setUncontrolledCat] = useState(
    () => defaultCategory ?? categories?.[0]?.id ?? '',
  )
  const resolvedCat = activeCategory !== undefined ? activeCategory : uncontrolledCat
  const [activeRowId, setActiveRowId] = useState<string | null>(null)

  useSlidingIndicator(tabsRef, open ? resolvedCat : false, {
    itemSelector: '.dsh-pop-tab',
    indicatorClass: 'dsh-pop-tabs-ind',
  })

  const isAnchored = anchorRef !== undefined
  const shouldPortal = portal ?? isAnchored
  const anchoredPlacement = useAnchoredPlacement({
    open: open && isAnchored,
    anchorRef: anchorRef ?? { current: null },
    panelRef,
    side,
    align,
    gap,
    margin: 12,
  })

  const { layerId, zIndex } = useOverlayLayer({
    open: open && (isAnchored || Boolean(onClose)),
    tier: 'popover',
    closeOnEscape: Boolean(onClose),
    containsNode: (node) =>
      Boolean(panelRef.current?.contains(node) || anchorRef?.current?.contains(node)),
    onEscape: onClose ? () => onClose() : undefined,
    onPointerDownOutside: onClose ? () => onClose() : undefined,
  })

  const applyHighlight = (nextId: string | null, scrollIntoView = false) => {
    const root = bodyRef.current
    let targetEl: HTMLElement | undefined
    if (root) {
      const allRows = Array.from(root.querySelectorAll<HTMLElement>('.dsh-pop-row'))
      for (const row of allRows) {
        if (nextId !== null && row.id === nextId) {
          row.setAttribute('data-highlighted', 'true')
          targetEl = row
        } else {
          row.removeAttribute('data-highlighted')
        }
      }
    }
    setActiveRowId(nextId)
    if (scrollIntoView && targetEl) {
      targetEl.scrollIntoView?.({ block: 'nearest' })
    }
  }

  const getNavigableRows = (): HTMLElement[] => {
    const root = bodyRef.current
    if (!root) return []
    return Array.from(root.querySelectorAll<HTMLElement>('.dsh-pop-row')).filter(
      (el) =>
        el.getAttribute('role') === 'option'
        && !el.classList.contains('is-disabled')
        && el.getAttribute('aria-disabled') !== 'true'
        && !el.closest('[hidden]'),
    )
  }

  useEffect(() => {
    if (!open) {
      setActiveRowId(null)
      lastPointerRef.current = null
      return
    }
    if (!autoFocusSearch || !showSearch) return
    const isCoarsePointer =
      typeof window !== 'undefined'
      && typeof window.matchMedia === 'function'
      && Boolean(window.matchMedia('(pointer: coarse)')?.matches)
    if (!isCoarsePointer) {
      searchInputRef.current?.focus?.({ preventScroll: true })
    }
  }, [open, autoFocusSearch, showSearch])

  if (!open) return null

  const updateSearch = (next: string) => {
    if (searchValue === undefined) setUncontrolledSearch(next)
    applyHighlight(null)
    onSearchChange?.(next)
  }

  const handleSearchKeyDown = (event: ReactKeyboardEvent<HTMLInputElement>) => {
    if (isImeComposing(event)) return
    if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
      const rows = getNavigableRows()
      if (rows.length === 0) return
      event.preventDefault()
      const curIdx = activeRowId ? rows.findIndex((r) => r.id === activeRowId) : -1
      const nextIdx =
        event.key === 'ArrowDown'
          ? curIdx >= 0
            ? (curIdx + 1) % rows.length
            : 0
          : curIdx >= 0
            ? (curIdx - 1 + rows.length) % rows.length
            : rows.length - 1
      const targetRow = rows[nextIdx]
      if (targetRow) {
        applyHighlight(targetRow.id, true)
      }
    } else if (event.key === 'Enter') {
      if (activeRowId !== null) {
        const rows = getNavigableRows()
        const activeRow = rows.find((r) => r.id === activeRowId)
        if (activeRow) {
          event.preventDefault()
          activeRow.click()
          return
        }
      }
      onSearchEnter?.(resolvedSearch)
    } else if (event.key === 'Escape') {
      if (resolvedSearch.length > 0) {
        event.preventDefault()
        event.stopPropagation?.()
        updateSearch('')
      } else if (onClose) {
        event.preventDefault()
        event.stopPropagation?.()
        onClose()
      }
    }
  }

  const selectCategory = (id: string) => {
    if (activeCategory === undefined) setUncontrolledCat(id)
    applyHighlight(null)
    onCategoryChange?.(id)
  }

  const hasTopBar = (categories !== undefined && categories.length > 0) || headerExtra !== undefined
  const resolvedSide = isAnchored ? (anchoredPlacement?.side ?? side) : rest['data-side']
  const resolvedOrigin = origin ?? (isAnchored ? anchoredPlacement?.origin : undefined)
  const resolvedPopAnim = isAnchored
    ? anchoredPlacement !== null || typeof window === 'undefined'
      ? 'true'
      : undefined
    : rest['data-pop-anim']

  const effectiveMaxBodyHeight =
    isAnchored && anchoredPlacement !== null && typeof maxBodyHeight === 'number'
      ? Math.max(96, Math.min(maxBodyHeight, anchoredPlacement.maxHeight - (showSearch ? 44 : 0) - (hasTopBar ? 36 : 0)))
      : maxBodyHeight

  const mergedStyle: CSSProperties = isAnchored
    ? {
        zIndex,
        ...(anchoredPlacement
          ? { left: anchoredPlacement.left, top: anchoredPlacement.top }
          : HIDDEN_POS),
        ...style,
      }
    : { ...style }

  const surface = (
    <OverlayParentContext.Provider value={layerId}>
      <PopoverModeContext.Provider value={{ combobox: showSearch }}>
        <MenuSurface
          {...rest}
          ref={mergeRefs(panelRef, forwardedRef)}
          material={material}
          origin={resolvedOrigin}
          data-dsh-portal={shouldPortal ? '' : undefined}
          data-side={resolvedSide}
          data-align={isAnchored ? align : rest['data-align']}
          data-pop-anim={resolvedPopAnim}
          className={`dsh-pop${isAnchored ? ' dsh-pop-anchored' : ''}${className ? ` ${className}` : ''}`}
          style={mergedStyle}
        >
          {showSearch && (
            <div className="dsh-pop-search">
              <span className="dsh-pop-search-ico" aria-hidden="true">
                <SearchIcon />
              </span>
              <input
                ref={searchInputRef}
                type="text"
                role="combobox"
                aria-expanded={open}
                aria-autocomplete="list"
                aria-controls={listboxId}
                aria-activedescendant={activeRowId ?? undefined}
                className="dsh-pop-search-input"
                value={resolvedSearch}
                placeholder={searchPlaceholder}
                aria-label={searchAriaLabel}
                onChange={(e) => updateSearch(e.target.value)}
                onKeyDown={handleSearchKeyDown}
              />
              {resolvedSearch.length > 0 && (
                <button
                  type="button"
                  className="dsh-pop-search-clear dsh-search-clear"
                  aria-label={clearSearchLabel}
                  onClick={() => {
                    updateSearch('')
                    searchInputRef.current?.focus?.()
                  }}
                >
                  <CloseIcon />
                </button>
              )}
            </div>
          )}

          {hasTopBar && (
            <div className="dsh-pop-top">
              {categories !== undefined && categories.length > 0 ? (
                <div
                  ref={tabsRef}
                  className="dsh-pop-tabs"
                  role="tablist"
                  aria-label={categoryAriaLabel}
                  onKeyDown={(e) => handleRovingKeyDown(e, '.dsh-pop-tab')}
                >
                  {categories.map((cat) => {
                    const selected = cat.id === resolvedCat
                    return (
                      <button
                        key={cat.id}
                        type="button"
                        role="tab"
                        tabIndex={selected ? 0 : -1}
                        aria-selected={selected}
                        disabled={cat.disabled}
                        className="dsh-pop-tab"
                        onClick={() => selectCategory(cat.id)}
                      >
                        {cat.label}
                      </button>
                    )
                  })}
                </div>
              ) : (
                <span />
              )}
              {headerExtra !== undefined && (
                <div className="dsh-pop-extra">{headerExtra}</div>
              )}
            </div>
          )}

          <ScrollArea
            maxHeight={effectiveMaxBodyHeight}
            thumbThreshold={1.05}
            viewportRef={bodyRef}
            viewportProps={{
              id: listboxId,
              role: showSearch ? 'listbox' : undefined,
              onPointerMove: showSearch
                ? (event) => {
                    if (!didPointerActuallyMove(lastPointerRef, event)) return
                    const targetEl =
                      event.target instanceof Element
                        ? event.target.closest<HTMLElement>('.dsh-pop-row')
                        : null
                    if (
                      targetEl
                      && targetEl.getAttribute('role') === 'option'
                      && !targetEl.classList.contains('is-disabled')
                      && targetEl.getAttribute('aria-disabled') !== 'true'
                    ) {
                      if (activeRowId !== targetEl.id) {
                        applyHighlight(targetEl.id)
                      }
                    }
                  }
                : undefined,
              onPointerLeave: showSearch
                ? () => {
                    lastPointerRef.current = null
                    if (activeRowId !== null) applyHighlight(null)
                  }
                : undefined,
            }}
            className="dsh-pop-scroll"
            viewportClassName="dsh-pop-body"
          >
            {children}
          </ScrollArea>

          {footer !== undefined && (
            <div className="dsh-pop-footer">{footer}</div>
          )}
        </MenuSurface>
      </PopoverModeContext.Provider>
    </OverlayParentContext.Provider>
  )

  if (shouldPortal && typeof document !== 'undefined' && Boolean(document.body)) {
    return createPortal(surface, document.body)
  }
  return surface
})

/* ---------- PopoverRow & PopoverGroup 辅助子原语 ---------- */

export interface PopoverRowProps extends Omit<HTMLAttributes<HTMLDivElement>, 'title' | 'onSelect'> {
  icon?: ReactNode
  title: ReactNode
  alias?: ReactNode
  description?: ReactNode
  info?: ReactNode
  infoLabel?: string
  starred?: boolean
  onToggleStar?: () => void
  starLabel?: string
  selected?: boolean
  disabled?: boolean
  onSelect?: () => void
  trailing?: ReactNode
}

export function PopoverRow({
  id,
  icon,
  title,
  alias,
  description,
  info,
  infoLabel,
  starred,
  onToggleStar,
  starLabel = '收藏',
  selected = false,
  disabled = false,
  onSelect,
  trailing,
  className,
  tabIndex,
  onClick,
  onKeyDown,
  ...rest
}: PopoverRowProps) {
  const autoId = useId()
  const resolvedId = id ?? `dsh-prow-${autoId.replaceAll(':', '')}`
  const { combobox } = useContext(PopoverModeContext)
  const interactive = onSelect !== undefined || onClick !== undefined
  const resolvedTabIndex =
    tabIndex !== undefined
      ? tabIndex
      : interactive && !disabled
        ? combobox
          ? -1
          : 0
        : undefined

  return (
    <div
      id={resolvedId}
      role={interactive ? 'option' : undefined}
      aria-selected={interactive ? selected : undefined}
      aria-disabled={disabled || undefined}
      tabIndex={resolvedTabIndex}
      data-combobox-row={combobox ? '' : undefined}
      {...rest}
      className={`dsh-pop-row${selected ? ' is-selected' : ''}${disabled ? ' is-disabled' : ''}${className ? ` ${className}` : ''}`}
      onClick={(event) => {
        if (disabled) return
        onClick?.(event)
        onSelect?.()
      }}
      onKeyDown={(event) => {
        onKeyDown?.(event)
        if (event.defaultPrevented || disabled || isImeComposing(event)) return
        if (event.target !== event.currentTarget) return
        if (interactive && (event.key === 'Enter' || event.key === ' ')) {
          event.preventDefault()
          onSelect?.()
        }
      }}
    >
      {icon !== undefined && (
        <span className="hs-fb-icon" aria-hidden="true">
          {icon}
        </span>
      )}
      <span className="dsh-pop-title">{title}</span>
      {alias !== undefined && <span className="dsh-pop-alias">{alias}</span>}
      {description !== undefined && <span className="dsh-pop-desc">{description}</span>}
      {trailing}
      {info !== undefined && info !== null && info !== '' && (
        <InfoTip
          content={info}
          label={infoLabel}
          preventFocusSteal
          tabIndex={combobox ? -1 : undefined}
        />
      )}
      {(starred !== undefined || onToggleStar !== undefined) && (
        <button
          type="button"
          tabIndex={combobox ? -1 : undefined}
          className="dsh-pop-star"
          aria-pressed={Boolean(starred)}
          aria-label={starLabel}
          onClick={(event) => {
            event.stopPropagation?.()
            onToggleStar?.()
          }}
        >
          <StarIcon filled={Boolean(starred)} />
        </button>
      )}
    </div>
  )
}

export interface PopoverGroupProps extends Omit<HTMLAttributes<HTMLDivElement>, 'title'> {
  title: ReactNode
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  children?: ReactNode
}

export function PopoverGroup({
  title,
  open,
  defaultOpen = true,
  onOpenChange,
  className,
  children,
  ...rest
}: PopoverGroupProps) {
  const headId = useId()
  const [uncontrolledOpen, setUncontrolledOpen] = useState(defaultOpen)
  const isOpen = open !== undefined ? open : uncontrolledOpen

  const toggle = () => {
    const next = !isOpen
    if (open === undefined) setUncontrolledOpen(next)
    onOpenChange?.(next)
  }

  return (
    <div
      role="group"
      aria-labelledby={headId}
      {...rest}
      className={`dsh-pop-group${className ? ` ${className}` : ''}`}
    >
      <button
        id={headId}
        type="button"
        className="dsh-pop-ghead"
        aria-expanded={isOpen}
        onClick={toggle}
      >
        <span className="dsh-pop-gchev" aria-hidden="true">
          <ChevronDownIcon />
        </span>
        <span>{title}</span>
      </button>
      <div className="dsh-pop-gbody" hidden={!isOpen}>
        {children}
      </div>
    </div>
  )
}

export const popoverCss = `
/* Popover 复合弹出面板（外框 16px - 边距 6px = 列表项 10px 严格同心） */
.dsh-pop {
  --dsh-r-outer: var(--dsw-radius-lg, 16px);
  --dsh-pad: 6px;
  padding: var(--dsh-pad);
  gap: 2px;
}
.dsh-pop-anchored {
  position: fixed;
  z-index: 1100;
  min-width: 240px;
  max-width: min(380px, calc(100vw - 24px));
}

/* 顶栏无框搜索条（严守 1-Border Rule：浮层内不重复画胶囊边框，底线两端留白 8px） */
.dsh-pop-search {
  position: relative;
  display: flex;
  align-items: center;
  gap: 7px;
  min-height: var(--dsh-row-sm, 32px);
  padding: 0 6px 5px 8px;
  margin-bottom: 2px;
}
.dsh-pop-search::after {
  content: "";
  position: absolute;
  left: 8px;
  right: 8px;
  bottom: 0;
  border-top: .5px solid var(--dsw-alias-border-l1);
  pointer-events: none;
}
.dsh-pop-search-ico {
  flex: none;
  display: inline-grid;
  place-items: center;
  width: 15px;
  height: 15px;
  font-size: var(--dsh-text-lg, 14px);
  color: var(--dsw-alias-label-tertiary);
}
.dsh-pop-search-input {
  all: unset;
  flex: 1;
  min-width: 0;
  font-size: var(--dsh-text-md, 13px);
  line-height: 20px;
  color: var(--dsw-alias-label-primary);
}
.dsh-pop-search-input::placeholder {
  color: var(--dsw-alias-label-tertiary);
}
@media (pointer: coarse) and (max-width: 768px) {
  .dsh-pop-search-input {
    font-size: var(--dsh-text-xl, 16px);
  }
}
.dsh-pop-search-clear {
  all: unset;
  position: relative;
  flex: none;
  width: var(--dsh-control-xs, 20px);
  height: var(--dsh-control-xs, 20px);
  border-radius: 50%;
  corner-shape: round;
  display: grid;
  place-items: center;
  font-size: var(--dsh-text-xs, 11px);
  color: var(--dsw-alias-label-tertiary);
  cursor: pointer;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
  transition:
    background var(--dsh-dur-hover, 120ms) ease,
    color var(--dsh-dur-hover, 120ms) ease,
    transform var(--dsh-dur-release, 150ms) var(--dsh-ease-out, cubic-bezier(.22, 1, .36, 1));
}
.dsh-pop-search-clear::after {
  content: "";
  position: absolute;
  inset: -4px;
  border-radius: 50%;
  corner-shape: round;
}
@media (pointer: coarse) {
  .dsh-pop-search-clear::after {
    inset: -8px;
  }
}
.dsh-pop-search-clear:active {
  transform: scale(.94);
  transition-duration: var(--dsh-dur-press, 60ms);
  transition-timing-function: var(--dsh-ease-out, cubic-bezier(.22, 1, .36, 1));
}
.dsh-pop-search-clear:focus-visible {
  outline: var(--dsw-focus-ring-width, 2px) solid var(--dsh-focus-ring-color);
  outline-offset: -2px;
}

/* 顶栏滑动胶囊分类筛选条 */
.dsh-pop-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  position: relative;
  padding: 0 2px 5px;
  margin-bottom: 2px;
}
.dsh-pop-top::after {
  content: "";
  position: absolute;
  left: 8px;
  right: 8px;
  bottom: 0;
  border-top: .5px solid var(--dsw-alias-border-l1);
  pointer-events: none;
}
.dsh-pop-extra {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex: none;
}
.dsh-pop-tabs {
  position: relative;
  isolation: isolate;
  display: inline-flex;
  align-items: center;
  min-width: 0;
  max-width: 100%;
  overflow-x: auto;
  scrollbar-width: none;
  gap: 2px;
}
.dsh-pop-tabs::-webkit-scrollbar {
  display: none;
}
.dsh-pop-tab {
  all: unset;
  box-sizing: border-box;
  flex: none;
  white-space: nowrap;
  height: calc(var(--dsh-control-sm, 28px) - 4px);
  padding: 0 9px;
  border-radius: 999px;
  corner-shape: round;
  font-size: var(--dsh-text-sm, 12px);
  font-weight: 500;
  color: var(--dsw-alias-label-tertiary);
  cursor: pointer;
  touch-action: manipulation;
  transition:
    background var(--dsh-dur-hover, 120ms) ease,
    color var(--dsh-dur-hover, 120ms) ease;
}
.dsh-pop-tab:disabled {
  opacity: .4;
  cursor: not-allowed;
}
.dsh-pop-tab:focus-visible {
  outline: var(--dsw-focus-ring-width, 2px) solid var(--dsh-focus-ring-color);
  outline-offset: -2px;
}
.dsh-pop-tab[aria-selected="true"],
.dsh-pop-tabs-ind {
  background: var(--dsw-alias-interactive-bg-hover);
}
.dsh-pop-tab[aria-selected="true"] {
  color: var(--dsw-alias-label-primary);
}
.dsh-pop-tabs[data-ind] .dsh-pop-tab[aria-selected="true"] {
  background: transparent;
}
.dsh-pop-tabs-ind {
  position: absolute;
  z-index: -1;
  top: 0;
  left: 0;
  height: calc(var(--dsh-control-sm, 28px) - 4px);
  border-radius: 999px;
  corner-shape: round;
  pointer-events: none;
  width: var(--ind-w, 0);
  transform: translateX(var(--ind-x, 0));
  transition:
    transform var(--dsh-dur-expand, 220ms) var(--dsh-ease-out, cubic-bezier(.22, 1, .36, 1)),
    width var(--dsh-dur-expand, 220ms) var(--dsh-ease-out, cubic-bezier(.22, 1, .36, 1));
}
.dsh-pop-tabs-ind[data-instant] {
  transition: none;
}
.dsh-pop-pin[aria-pressed="true"] {
  color: var(--dsw-alias-state-business-primary);
}

/* ScrollArea 主体列表区 */
.dsh-pop-scroll {
  min-height: 0;
}
.dsh-pop-body {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

/* 10px 同心列表行与星标收藏按钮 */
.dsh-pop-row {
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: var(--dsh-row-sm, 32px);
  padding: 4px 8px;
  border-radius: max(0px, calc(var(--dsh-r-outer) - var(--dsh-pad)));
  corner-shape: var(--dsh-corner-shape, var(--dsw-corner-shape, round));
  font-size: var(--dsh-text-md, 13px);
  color: var(--dsw-alias-label-primary);
  cursor: pointer;
}
.dsh-pop-row[data-highlighted="true"]:not(.is-disabled):not([aria-disabled="true"]) {
  background: var(--dsw-alias-interactive-bg-hover);
}
.dsh-pop-row.is-selected,
.dsh-pop-row[aria-selected="true"] {
  background: var(--dsw-alias-interactive-bg-active);
}
.dsh-pop-row.is-disabled,
.dsh-pop-row[aria-disabled="true"] {
  opacity: .42;
  cursor: not-allowed;
}
.dsh-pop-row:focus-visible {
  outline: var(--dsw-focus-ring-width, 2px) solid var(--dsh-focus-ring-color);
  outline-offset: -2px;
}
.dsh-pop-title {
  font-weight: 500;
}
.dsh-pop-alias {
  flex: none;
  font-family: var(--ds-font-family-code, monospace);
  font-size: var(--dsh-text-sm, 12px);
  color: var(--dsw-alias-label-tertiary);
}
.dsh-pop-desc {
  flex: 0 1 auto;
  min-width: 0;
  margin-left: auto;
  font-size: var(--dsh-text-sm, 12px);
  color: var(--dsw-alias-label-tertiary);
  white-space: nowrap;
}
.dsh-pop-row > * {
  min-width: 0;
  white-space: nowrap;
}
.dsh-pop-row > span:not(.hs-fb-icon):not(.dsh-pop-alias) {
  overflow: hidden;
  text-overflow: ellipsis;
}
.dsh-pop-row:has(> .dsh-pop-desc) > span:not(.hs-fb-icon):not(.dsh-pop-alias):not(.dsh-pop-desc) {
  flex: 0 1 auto;
  flex-shrink: 0;
  max-width: 62%;
}

.dsh-pop-star {
  all: unset;
  position: relative;
  flex: none;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  corner-shape: round;
  display: grid;
  place-items: center;
  color: var(--dsw-alias-label-caption);
  font-size: var(--dsh-text-md, 13px);
  cursor: pointer;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
  transition:
    background var(--dsh-dur-hover, 120ms) ease,
    color var(--dsh-dur-hover, 120ms) ease,
    transform var(--dsh-dur-release, 150ms) var(--dsh-ease-out, cubic-bezier(.22, 1, .36, 1));
}
.dsh-pop-star::after {
  content: "";
  position: absolute;
  inset: -4px;
  border-radius: 50%;
  corner-shape: round;
}
@media (pointer: coarse) {
  .dsh-pop-star::after {
    inset: -4px;
  }
}
.dsh-pop-star:active {
  transform: scale(.93);
  transition-duration: var(--dsh-dur-press, 60ms);
  transition-timing-function: var(--dsh-ease-out, cubic-bezier(.22, 1, .36, 1));
}
.dsh-pop-star:focus-visible {
  outline: var(--dsw-focus-ring-width, 2px) solid var(--dsh-focus-ring-color);
  outline-offset: -2px;
}
.dsh-pop-star[aria-pressed="true"] {
  color: var(--dsw-alias-state-warn-primary);
}

/* 可折叠底部快捷开关组 */
.dsh-pop-group {
  margin-top: 3px;
  display: flex;
  flex-direction: column;
  gap: 1px;
}
.dsh-pop-group::before {
  content: "";
  display: block;
  margin: 0 8px 3px;
  border-top: .5px solid var(--dsw-alias-border-l2);
}
.dsh-pop-ghead {
  all: unset;
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: 5px;
  height: 26px;
  padding: 0 8px;
  border-radius: var(--dsw-radius-sm, 8px);
  corner-shape: var(--dsh-corner-shape, var(--dsw-corner-shape, round));
  font-size: var(--dsh-text-sm, 12px);
  font-weight: 500;
  color: var(--dsw-alias-label-secondary);
  cursor: pointer;
}
.dsh-pop-ghead:focus-visible {
  outline: var(--dsw-focus-ring-width, 2px) solid var(--dsh-focus-ring-color);
  outline-offset: -2px;
}
.dsh-pop-gchev {
  display: inline-flex;
  font-size: var(--dsh-text-2xs, 10px);
  color: var(--dsw-alias-label-tertiary);
  transition: transform var(--dsh-dur-expand, 220ms) var(--dsh-ease-out, cubic-bezier(.22, 1, .36, 1));
}
.dsh-pop-ghead[aria-expanded="false"] .dsh-pop-gchev {
  transform: rotate(-90deg);
}
.dsh-pop-gbody[hidden] {
  display: none;
}

/* 底部快捷键提示底栏 */
.dsh-pop-footer {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 6px 8px 2px;
  margin-top: 2px;
  font-size: var(--dsh-text-xs, 11px);
  line-height: 1.4;
  color: var(--dsw-alias-label-tertiary);
}
.dsh-pop-footer::before {
  content: "";
  position: absolute;
  left: 8px;
  right: 8px;
  top: 0;
  border-top: .5px solid var(--dsw-alias-border-l1);
  pointer-events: none;
}

@media (hover: hover) {
  .dsh-pop-search-clear:hover {
    background: var(--dsw-alias-interactive-bg-hover);
    color: var(--dsw-alias-label-primary);
  }
  .dsh-pop-tab:not(:disabled):hover {
    color: var(--dsw-alias-label-primary);
  }
  .dsh-pop-row:not([data-combobox-row]):not(.is-disabled):not([aria-disabled="true"]):hover {
    background: var(--dsw-alias-interactive-bg-hover);
  }
  .dsh-pop-star:hover {
    background: var(--dsw-alias-interactive-bg-hover);
    color: var(--dsw-alias-label-secondary);
  }
  .dsh-pop-ghead:hover {
    color: var(--dsw-alias-label-primary);
  }
}
`
