const SVG_NS = 'http://www.w3.org/2000/svg'

/* ---------- 内部跨环境 DOM 兼容辅助（兼容真实浏览器、JSDOM 与单测轻量 MockDOM） ---------- */

function splitClasses(cls: string | undefined | null): string[] {
  return (cls ?? '').split(/\s+/).filter(Boolean)
}

function hasClass(el: Element | null | undefined, cls: string): boolean {
  if (!el) return false
  if (el.classList && typeof el.classList.contains === 'function') {
    return el.classList.contains(cls)
  }
  return splitClasses((el as HTMLElement).className).includes(cls)
}

function addClass(el: HTMLElement, ...names: Array<string | undefined | null | false>): void {
  const toAdd = names.flatMap((n) => (typeof n === 'string' ? splitClasses(n) : []))
  if (toAdd.length === 0) return
  if (el.classList && typeof el.classList.add === 'function') {
    el.classList.add(...toAdd)
    return
  }
  const existing = splitClasses(el.className)
  for (const c of toAdd) {
    if (!existing.includes(c)) existing.push(c)
  }
  el.className = existing.join(' ')
}

function removeClass(el: HTMLElement, ...names: string[]): void {
  if (names.length === 0) return
  if (el.classList && typeof el.classList.remove === 'function') {
    el.classList.remove(...names)
    return
  }
  const drop = new Set(names)
  el.className = splitClasses(el.className)
    .filter((c) => !drop.has(c))
    .join(' ')
}

function getDirectChildren(el: HTMLElement): HTMLElement[] {
  return Array.from(el.children ?? []) as HTMLElement[]
}

function getAllChildNodes(el: HTMLElement): Node[] {
  if (el.childNodes && typeof el.childNodes.length === 'number') {
    return Array.from(el.childNodes)
  }
  return Array.from(el.children ?? [])
}

function prependChild(parent: HTMLElement, child: Node): void {
  if (typeof parent.prepend === 'function') {
    parent.prepend(child)
  } else {
    parent.insertBefore(child, parent.firstChild ?? null)
  }
}

function isNodeConnected(el: HTMLElement | null | undefined, doc?: Document | null): boolean {
  if (!el) return false
  if (typeof el.isConnected === 'boolean') return el.isConnected
  const owner = doc ?? el.ownerDocument
  return Boolean(owner?.documentElement?.contains?.(el))
}

function setStylePxOrClear(
  style: CSSStyleDeclaration,
  prop: 'left' | 'right' | 'top' | 'bottom' | 'max-width',
  camel: 'left' | 'right' | 'top' | 'bottom' | 'maxWidth',
  val: number | undefined,
): void {
  if (typeof val === 'number' && Number.isFinite(val)) {
    const px = `${val}px`
    if (typeof style.setProperty === 'function') style.setProperty(prop, px)
    ;(style as unknown as Record<string, string>)[camel] = px
  } else {
    if (typeof style.removeProperty === 'function') style.removeProperty(prop)
    ;(style as unknown as Record<string, string>)[camel] = ''
  }
}

function createSvgIcon(
  doc: Document,
  pathData: string,
  size: number,
  extraClass?: string,
): SVGSVGElement {
  const svg = (
    typeof doc.createElementNS === 'function'
      ? doc.createElementNS(SVG_NS, 'svg')
      : doc.createElement('svg')
  ) as unknown as SVGSVGElement
  const cls = extraClass ? `dsh-icon ${extraClass}` : 'dsh-icon'
  svg.setAttribute('class', cls)
  if (!('classList' in svg)) {
    ;(svg as unknown as { className: string }).className = cls
  }
  svg.setAttribute('viewBox', '0 0 16 16')
  svg.setAttribute('width', String(size))
  svg.setAttribute('height', String(size))
  svg.setAttribute('fill', 'none')
  svg.setAttribute('stroke', 'currentColor')
  svg.setAttribute('stroke-width', '1.5')
  svg.setAttribute('stroke-linecap', 'round')
  svg.setAttribute('stroke-linejoin', 'round')
  svg.setAttribute('focusable', 'false')
  svg.setAttribute('aria-hidden', 'true')

  const path = (
    typeof doc.createElementNS === 'function'
      ? doc.createElementNS(SVG_NS, 'path')
      : doc.createElement('path')
  ) as unknown as SVGPathElement
  path.setAttribute('d', pathData)
  svg.appendChild(path)
  return svg
}

function findMatchingItemInMenu(
  menu: HTMLElement,
  target: unknown,
  itemSelector: string,
): HTMLElement | null {
  if (!target || typeof target !== 'object') return null
  const maybeEl = target as HTMLElement & { parentElement?: HTMLElement | null }
  if (typeof maybeEl.closest === 'function') {
    try {
      const hit = maybeEl.closest<HTMLElement>(itemSelector)
      if (hit && menu.contains(hit)) return hit
    } catch {
      /* fallback below */
    }
  }
  const candidates = Array.from(menu.querySelectorAll<HTMLElement>(itemSelector))
  for (const item of candidates) {
    if (item === maybeEl || (typeof item.contains === 'function' && item.contains(maybeEl as Node))) {
      return item
    }
  }
  return null
}

/* ---------- 1. 输入模态追踪（pointer / keyboard） ---------- */

const MODALITY_KEYS = new Set([
  'Tab',
  'ArrowUp',
  'ArrowDown',
  'ArrowLeft',
  'ArrowRight',
  'Home',
  'End',
  'PageUp',
  'PageDown',
  'Enter',
  ' ',
  'Escape',
])

interface ModalityEntry {
  count: number
  dispose: () => void
}

const modalityRegistry = new WeakMap<Document, ModalityEntry>()

/**
 * 引用计数安装文档级输入模态追踪器，将最近一次交互写入 html[data-input-modality="pointer" | "keyboard"]。
 */
export function installInputModality(doc: Document): () => void {
  if (!doc || typeof doc.addEventListener !== 'function') return () => {}
  let entry = modalityRegistry.get(doc)
  if (!entry) {
    const setModality = (mode: 'pointer' | 'keyboard') => {
      const root = doc.documentElement
      if (!root) return
      root.setAttribute('data-input-modality', mode)
      if (root.dataset) root.dataset.inputModality = mode
    }
    const onPointerDown = () => {
      setModality('pointer')
    }
    const onKeyDown = (e: KeyboardEvent) => {
      if (!e || e.metaKey || e.ctrlKey || e.altKey) return
      if (MODALITY_KEYS.has(e.key)) {
        setModality('keyboard')
      }
    }
    doc.addEventListener('pointerdown', onPointerDown, true)
    doc.addEventListener('keydown', onKeyDown, true)
    entry = {
      count: 0,
      dispose() {
        doc.removeEventListener('pointerdown', onPointerDown, true)
        doc.removeEventListener('keydown', onKeyDown, true)
      },
    }
    modalityRegistry.set(doc, entry)
  }
  entry.count += 1
  const currentEntry = entry
  let active = true
  return () => {
    if (!active) return
    active = false
    currentEntry.count -= 1
    if (currentEntry.count <= 0) {
      currentEntry.dispose()
      modalityRegistry.delete(doc)
    }
  }
}

/* ---------- 2. 滑动选中指示块（Segmented / UnderlineTabs 通用） ---------- */

export interface MountSlidingIndicatorOptions {
  itemSelector?: string
  indicatorClass?: string
}

export interface SlidingIndicatorHandle {
  sync: (instant?: boolean) => void
  destroy: () => void
}

const DEFAULT_SLIDING_ITEM_SELECTOR = '[role="tab"], .dsh-seg-item, .dsh-utab, button'

function isSlidingCandidateSelected(el: HTMLElement): boolean {
  return (
    el.getAttribute('aria-selected') === 'true'
    || el.getAttribute('aria-pressed') === 'true'
    || el.getAttribute('aria-current') === 'page'
  )
}

function measureSelectedItem(
  container: HTMLElement,
  itemSelector: string,
  ignoreEl: HTMLElement,
): { el: HTMLElement; left: number; width: number } | null {
  const candidates = Array.from(container.querySelectorAll<HTMLElement>(itemSelector))
  const sel = candidates.find((el) => el !== ignoreEl && isSlidingCandidateSelected(el))
  if (!sel) return null

  let width = sel.offsetWidth || 0
  let left = sel.offsetLeft || 0

  if (width === 0 && typeof sel.getBoundingClientRect === 'function') {
    const itemRect = sel.getBoundingClientRect()
    width = Math.round(itemRect.width)
    if (typeof container.getBoundingClientRect === 'function') {
      const parentRect = container.getBoundingClientRect()
      left = Math.round(itemRect.left - parentRect.left)
    }
  }

  return { el: sel, left, width }
}

/**
 * 为分段胶囊（.dsh-seg）或下划线标签栏（.dsh-utabs）挂载平滑滑动选中指示器：
 * - 自动识别 aria-selected="true" / aria-pressed="true" / aria-current="page"；
 * - 首次挂载、零宽恢复、子项增删及尺寸变化瞬时对齐（同步 offsetWidth 刷帧消除飞入残影），状态切换平滑过渡。
 */
export function mountSlidingIndicator(
  container: HTMLElement,
  options?: MountSlidingIndicatorOptions,
): SlidingIndicatorHandle {
  if (!container || !container.ownerDocument) {
    return { sync() {}, destroy() {} }
  }
  const doc = container.ownerDocument
  const win = doc.defaultView
  const itemSelector = options?.itemSelector ?? DEFAULT_SLIDING_ITEM_SELECTOR
  const indicatorClass =
    options?.indicatorClass ?? (hasClass(container, 'dsh-utabs') ? 'dsh-utabs-ind' : 'dsh-seg-ind')

  let ind = getDirectChildren(container).find((c) => hasClass(c, indicatorClass)) ?? null
  const createdInd = ind === null
  if (!ind) {
    ind = doc.createElement('span')
    ind.className = indicatorClass
    ind.setAttribute('aria-hidden', 'true')
    prependChild(container, ind)
  }
  const indicatorEl = ind
  container.setAttribute('data-ind', '')

  const expandTransition =
    'transform var(--dsh-dur-expand, 220ms) var(--dsh-ease-out, cubic-bezier(.22, 1, .36, 1)), width var(--dsh-dur-expand, 220ms) var(--dsh-ease-out, cubic-bezier(.22, 1, .36, 1))'

  let disposed = false
  let hasPlaced = false
  let rafId = 0
  const raf =
    typeof win?.requestAnimationFrame === 'function' ? win.requestAnimationFrame.bind(win) : null
  const cancelRaf =
    typeof win?.cancelAnimationFrame === 'function' ? win.cancelAnimationFrame.bind(win) : null

  const place = (instant = false) => {
    if (disposed) return
    const measured = measureSelectedItem(container, itemSelector, indicatorEl)
    if (!measured) {
      indicatorEl.style.opacity = '0'
      return
    }
    if (measured.width <= 0) {
      hasPlaced = false
      indicatorEl.style.opacity = '0'
      return
    }
    const useInstant = Boolean(instant) || !hasPlaced
    hasPlaced = true
    if (useInstant) {
      indicatorEl.setAttribute('data-instant', '')
      indicatorEl.style.transition = 'none'
    } else {
      indicatorEl.removeAttribute('data-instant')
      indicatorEl.style.transition = expandTransition
    }
    indicatorEl.style.opacity = ''
    indicatorEl.style.setProperty('--ind-x', `${measured.left}px`)
    indicatorEl.style.setProperty('--ind-w', `${measured.width}px`)
    indicatorEl.style.width = `${measured.width}px`
    indicatorEl.style.transform = `translateX(${measured.left}px)`
    if (useInstant) {
      void indicatorEl.offsetWidth
      indicatorEl.removeAttribute('data-instant')
    }
  }

  const ResizeCtor =
    (win as unknown as { ResizeObserver?: typeof ResizeObserver } | null)?.ResizeObserver
    ?? globalThis.ResizeObserver
  const observedItems = new Set<HTMLElement>()
  const ro = ResizeCtor
    ? new ResizeCtor(() => {
        place(true)
      })
    : null

  const syncObservedItems = () => {
    if (!ro || disposed) return
    const nextItems = new Set(
      Array.from(container.querySelectorAll<HTMLElement>(itemSelector)).filter(
        (el) => el !== indicatorEl,
      ),
    )
    for (const prev of observedItems) {
      if (!nextItems.has(prev)) {
        ro.unobserve?.(prev)
        observedItems.delete(prev)
      }
    }
    for (const item of nextItems) {
      if (!observedItems.has(item)) {
        ro.observe(item)
        observedItems.add(item)
      }
    }
  }

  ro?.observe(container)
  syncObservedItems()

  const MutationCtor =
    (win as unknown as { MutationObserver?: typeof MutationObserver } | null)?.MutationObserver
    ?? globalThis.MutationObserver
  const mo = MutationCtor
    ? new MutationCtor((records) => {
        if (!Array.isArray(records)) {
          place(false)
          return
        }
        const hasChildList = records.some((r) => r?.type === 'childList')
        const hasDirectChildList = records.some(
          (r) => r?.type === 'childList' && r.target === container,
        )
        const hasAttr = records.some((r) => r?.type === 'attributes')
        if (hasChildList) syncObservedItems()
        if (hasAttr && !hasDirectChildList) {
          place(false)
        } else if (hasChildList) {
          place(true)
        } else {
          place(false)
        }
      })
    : null
  mo?.observe(container, {
    attributes: true,
    attributeFilter: ['aria-selected', 'aria-pressed', 'aria-current'],
    childList: true,
    subtree: true,
  })

  place(true)
  if (!hasPlaced && raf) {
    rafId = raf(() => {
      rafId = 0
      if (!disposed && !hasPlaced) place(true)
    })
  }
  const fonts = (doc as unknown as { fonts?: { ready?: Promise<unknown> } }).fonts
  if (fonts?.ready) {
    void fonts.ready.then(() => {
      if (!disposed) place(true)
    })
  }

  return {
    sync: (instant = false) => place(Boolean(instant)),
    destroy() {
      if (disposed) return
      disposed = true
      if (rafId && cancelRaf) {
        cancelRaf(rafId)
        rafId = 0
      }
      mo?.disconnect()
      ro?.disconnect()
      observedItems.clear()
      if (createdInd) indicatorEl.remove()
      container.removeAttribute('data-ind')
    },
  }
}

/* ---------- 3. ScrollArea 命令式容器挂载器 ---------- */

export interface MountScrollAreaOptions {
  thumbThreshold?: number
  frameClassName?: string
  viewportClassName?: string
}

export interface ScrollAreaHandle {
  frame: HTMLDivElement
  viewport: HTMLDivElement
  thumb: HTMLDivElement
  sync: () => void
  destroy: () => void
}

const scrollAreaRegistry = new WeakMap<HTMLElement, ScrollAreaHandle>()

/**
 * 在目标容器内构建 .dsh-scroll-frame > (.dsh-scroll-area[role="none"] + .dsh-scroll-thumb) 并绑定滚动渐隐与滑块拖拽。
 */
export function mountScrollArea(
  container: HTMLElement,
  options?: MountScrollAreaOptions,
): ScrollAreaHandle {
  const existing = scrollAreaRegistry.get(container)
  if (existing) {
    existing.sync()
    return existing
  }

  const doc = container.ownerDocument
  const win = doc?.defaultView
  const thumbThreshold = options?.thumbThreshold ?? 1.05

  let frame = getDirectChildren(container).find((c) => hasClass(c, 'dsh-scroll-frame')) as
    | HTMLDivElement
    | undefined
  if (!frame) {
    frame = doc.createElement('div')
    frame.className = 'dsh-scroll-frame'
  }
  if (options?.frameClassName) addClass(frame, options.frameClassName)

  let viewport = getDirectChildren(frame).find((c) => hasClass(c, 'dsh-scroll-area')) as
    | HTMLDivElement
    | undefined
  if (!viewport) {
    viewport = doc.createElement('div')
    viewport.className = 'dsh-scroll-area'
    viewport.setAttribute('role', 'none')
  }
  if (options?.viewportClassName) addClass(viewport, options.viewportClassName)

  let thumb = getDirectChildren(frame).find((c) => hasClass(c, 'dsh-scroll-thumb')) as
    | HTMLDivElement
    | undefined
  if (!thumb) {
    thumb = doc.createElement('div')
    thumb.className = 'dsh-scroll-thumb'
    thumb.setAttribute('aria-hidden', 'true')
    thumb.hidden = true
  }

  for (const child of getAllChildNodes(container)) {
    if (child === frame) continue
    if (
      child instanceof Object
      && (hasClass(child as Element, 'hs-msurf-material')
        || hasClass(child as Element, 'hs-msurf-footer'))
    ) {
      continue
    }
    viewport.appendChild(child)
  }

  if (viewport.parentElement !== frame) frame.appendChild(viewport)
  if (thumb.parentElement !== frame) frame.appendChild(thumb)

  if (frame.parentElement !== container) {
    const footerEl = getDirectChildren(container).find((c) => hasClass(c, 'hs-msurf-footer'))
    if (footerEl) {
      container.insertBefore(frame, footerEl)
    } else {
      container.appendChild(frame)
    }
  }

  const core = attachScrollAreaWithSync(viewport, { thumbThreshold })

  let destroyed = false
  let openRafId = 0
  const raf =
    typeof win?.requestAnimationFrame === 'function' ? win.requestAnimationFrame.bind(win) : null
  const cancelRaf =
    typeof win?.cancelAnimationFrame === 'function' ? win.cancelAnimationFrame.bind(win) : null

  const MutationCtor =
    (win as unknown as { MutationObserver?: typeof MutationObserver } | null)?.MutationObserver
    ?? globalThis.MutationObserver
  const moContainer = MutationCtor
    ? new MutationCtor(() => {
        if (!destroyed && !container.hidden) {
          core.sync()
          if (openRafId && cancelRaf) cancelRaf(openRafId)
          if (raf) {
            openRafId = raf(() => {
              openRafId = 0
              if (!destroyed && !container.hidden) core.sync()
            })
          }
        }
      })
    : null
  moContainer?.observe(container, { attributes: true, attributeFilter: ['hidden'] })

  const handle: ScrollAreaHandle = {
    frame,
    viewport,
    thumb,
    sync: () => core.sync(),
    destroy() {
      if (destroyed) return
      destroyed = true
      if (openRafId && cancelRaf) {
        cancelRaf(openRafId)
        openRafId = 0
      }
      moContainer?.disconnect()
      core.dispose()
      scrollAreaRegistry.delete(container)
    },
  }
  scrollAreaRegistry.set(container, handle)
  return handle
}

/* ---------- 4. 菜单视口翻转、单一高亮游标与纵向键盘导航 ---------- */

/**
 * 菜单底部溢出视口安全区且触发器上方空间更充裕时，自动切换 data-side="top" 向上展开。
 */
export function fitMenuInViewport(menu: HTMLElement, win?: Window | null): void {
  if (!menu) return
  const targetWin =
    win ?? menu.ownerDocument?.defaultView ?? (typeof window !== 'undefined' ? window : null)
  if (!targetWin || typeof menu.getBoundingClientRect !== 'function') return
  let r = menu.getBoundingClientRect()
  if (!r || (r.width === 0 && r.height === 0)) return
  if (menu.hasAttribute('data-side')) {
    menu.removeAttribute('data-side')
    r = menu.getBoundingClientRect()
  }
  const vh = targetWin.innerHeight || 0
  if (vh > 0 && r.bottom > vh - 12) {
    const anchorRect = menu.parentElement?.getBoundingClientRect?.()
    if (anchorRect && anchorRect.top > vh - anchorRect.bottom) {
      menu.setAttribute('data-side', 'top')
      return
    }
  }
  menu.removeAttribute('data-side')
}

function applyMenuHighlight(
  menu: HTMLElement,
  itemSelector: string,
  target: HTMLElement | null,
): void {
  const items = Array.from(menu.querySelectorAll<HTMLElement>(itemSelector))
  for (const el of items) {
    if (target !== null && el === target) {
      el.setAttribute('data-highlighted', 'true')
    } else {
      el.removeAttribute('data-highlighted')
    }
  }
  if (target !== null) {
    menu.setAttribute('data-has-highlight', 'true')
  } else {
    menu.removeAttribute('data-has-highlight')
  }
}

/**
 * 为菜单挂载单一高亮游标管理（data-menu-managed + data-highlighted="true"），
 * 指针移动时同步焦点，离开菜单或菜单隐藏时自动清空高亮。
 */
export function wireMenuHighlight(
  menu: HTMLElement,
  itemSelector: string,
  doc: Document | undefined = menu?.ownerDocument ?? undefined,
): () => void {
  if (!menu) return () => {}
  menu.setAttribute('data-menu-managed', '')

  let lastX: number | null = null
  let lastY: number | null = null

  const onMove = (e: PointerEvent) => {
    if (e.pointerType === 'touch') return
    if (typeof e.clientX === 'number' && typeof e.clientY === 'number' && Number.isFinite(e.clientX) && Number.isFinite(e.clientY)) {
      if (e.clientX === lastX && e.clientY === lastY) return
      lastX = e.clientX
      lastY = e.clientY
    }
    const item = findMatchingItemInMenu(menu, e.target, itemSelector)
    if (
      !item
      || !menu.contains(item)
      || (item as HTMLButtonElement).disabled
      || item.getAttribute('aria-disabled') === 'true'
    ) {
      applyMenuHighlight(menu, itemSelector, null)
      return
    }
    applyMenuHighlight(menu, itemSelector, item)
    if (!doc || doc.activeElement !== item) {
      item.focus?.({ preventScroll: true })
    }
  }

  const onLeave = () => {
    lastX = null
    lastY = null
    applyMenuHighlight(menu, itemSelector, null)
  }

  const win = doc?.defaultView ?? menu.ownerDocument?.defaultView
  const MutationCtor =
    (win as unknown as { MutationObserver?: typeof MutationObserver } | null)?.MutationObserver
    ?? globalThis.MutationObserver
  const mo = MutationCtor
    ? new MutationCtor(() => {
        if (menu.hidden) {
          lastX = null
          lastY = null
          applyMenuHighlight(menu, itemSelector, null)
        }
      })
    : null
  mo?.observe(menu, { attributes: true, attributeFilter: ['hidden'] })

  menu.addEventListener('pointermove', onMove)
  menu.addEventListener('pointerleave', onLeave)

  return () => {
    mo?.disconnect()
    menu.removeEventListener('pointermove', onMove)
    menu.removeEventListener('pointerleave', onLeave)
  }
}

/**
 * 菜单纵向键盘导航（ArrowDown / ArrowUp / Home / End），推进单一 data-highlighted 游标并同步焦点。
 */
export function stepMenuKey(
  e: KeyboardEvent,
  menu: HTMLElement,
  itemSelector: string,
  doc: Document | undefined = menu?.ownerDocument ?? undefined,
): boolean {
  if (!e || !menu || isImeComposing(e)) return false
  if (
    e.key !== 'ArrowDown'
    && e.key !== 'ArrowUp'
    && e.key !== 'Home'
    && e.key !== 'End'
  ) {
    return false
  }
  const items = Array.from(menu.querySelectorAll<HTMLElement>(itemSelector)).filter(
    (el) =>
      !(el as HTMLButtonElement).disabled
      && el.getAttribute('aria-disabled') !== 'true'
      && !el.hidden
      && el.getAttribute('aria-hidden') !== 'true',
  )
  if (items.length === 0) return false

  let curIdx = items.findIndex((el) => el.getAttribute('data-highlighted') === 'true')
  if (curIdx < 0 && doc?.activeElement) {
    curIdx = items.indexOf(doc.activeElement as HTMLElement)
  }

  let nextIdx = 0
  if (e.key === 'ArrowDown') nextIdx = curIdx < 0 ? 0 : (curIdx + 1) % items.length
  else if (e.key === 'ArrowUp') nextIdx = curIdx <= 0 ? items.length - 1 : curIdx - 1
  else if (e.key === 'Home') nextIdx = 0
  else if (e.key === 'End') nextIdx = items.length - 1

  const next = items[nextIdx]
  if (!next) return false

  e.preventDefault?.()
  menu.setAttribute('data-menu-managed', '')
  applyMenuHighlight(menu, itemSelector, next)
  next.focus?.({ preventScroll: true })
  next.scrollIntoView?.({ block: 'nearest' })
  return true
}

/* ---------- 5. MenuSurface 命令式浮层挂载器（含 .hs-msurf-material 与 body backing） ---------- */

export interface MountMenuSurfaceOptions {
  compact?: boolean
  material?: 'translucent' | 'solid' | 'optical'
  scrollable?: boolean
  itemSelector?: string
  win?: Window | null
}

export interface MenuSurfaceHandle {
  menu: HTMLElement
  viewport: HTMLElement
  backing: HTMLDivElement | null
  sync: () => void
  destroy: () => void
}

let menuSurfaceUid = 0
const menuSurfaceRegistry = new WeakMap<HTMLElement, MenuSurfaceHandle>()

/**
 * 将任意浮层节点升级为标准 MenuSurface：
 * - 注入 .hs-msurf（及 .hs-msurf-compact）、data-menu-material、data-menu-managed、data-pop-anim 与唯一 --dsh-menu-anchor；
 * - translucent 档自动前置 .hs-msurf-material 磨砂隔离层，并在 menu 处于连接且非 hidden 态时向 body 挂载同步的 .hs-msurf-backing；
 * - 默认内嵌 mountScrollArea（.hs-msurf-scroll > .hs-msurf-scroll-body），可选绑定 wireMenuHighlight。
 */
export function mountMenuSurface(
  menu: HTMLElement,
  options?: MountMenuSurfaceOptions,
): MenuSurfaceHandle {
  const existing = menuSurfaceRegistry.get(menu)
  if (existing) {
    existing.sync()
    return existing
  }

  const doc = menu.ownerDocument
  const win = options?.win ?? doc?.defaultView ?? null
  const compact = Boolean(options?.compact)
  const material = options?.material ?? 'translucent'
  const scrollable = options?.scrollable !== false
  const anchorName = `--dsh-msurf-${++menuSurfaceUid}`

  addClass(menu, 'hs-msurf', compact ? 'hs-msurf-compact' : undefined)
  menu.setAttribute('data-menu-material', material)
  menu.setAttribute('data-menu-managed', '')
  menu.setAttribute('data-pop-anim', 'true')
  menu.style.setProperty('--dsh-menu-anchor', anchorName)

  let materialEl: HTMLDivElement | null = null
  let backing: HTMLDivElement | null = null

  if (material === 'translucent') {
    materialEl =
      (getDirectChildren(menu).find((c) => hasClass(c, 'hs-msurf-material')) as
        | HTMLDivElement
        | undefined) ?? null
    if (!materialEl) {
      materialEl = doc.createElement('div')
      materialEl.className = 'hs-msurf-material'
      materialEl.setAttribute('aria-hidden', 'true')
      prependChild(menu, materialEl)
    }

    backing = doc.createElement('div')
    backing.className = compact ? 'hs-msurf-backing hs-msurf-compact' : 'hs-msurf-backing'
    backing.setAttribute('data-menu-backing', '')
    backing.setAttribute('data-dsh-portal', '')
    backing.setAttribute('data-pop-anim', 'true')
    backing.setAttribute('aria-hidden', 'true')
    backing.style.setProperty('--dsh-menu-anchor', anchorName)
  }

  const scrollHandle = scrollable
    ? mountScrollArea(menu, {
        thumbThreshold: 1.05,
        frameClassName: 'hs-msurf-scroll',
        viewportClassName: 'hs-msurf-scroll-body',
      })
    : null
  const viewport = scrollHandle ? scrollHandle.viewport : menu

  const stopHighlight = options?.itemSelector
    ? wireMenuHighlight(menu, options.itemSelector, doc)
    : null

  let destroyed = false
  const MutationCtor =
    (win as unknown as { MutationObserver?: typeof MutationObserver } | null)?.MutationObserver
    ?? globalThis.MutationObserver
  let bodyObserver: MutationObserver | null = null
  let observingBody = false

  const syncBacking = () => {
    if (!backing) return
    if (destroyed) {
      backing.remove()
      if (observingBody) {
        bodyObserver?.disconnect()
        observingBody = false
      }
      return
    }

    const side = menu.getAttribute('data-side')
    if (side) backing.setAttribute('data-side', side)
    else backing.removeAttribute('data-side')

    const align = menu.getAttribute('data-align')
    if (align) backing.setAttribute('data-align', align)
    else backing.removeAttribute('data-align')

    const origin = menu.style.getPropertyValue('--dsh-pop-origin')
    if (origin) backing.style.setProperty('--dsh-pop-origin', origin)
    else backing.style.removeProperty('--dsh-pop-origin')

    const modalOverlay =
      typeof menu.closest === 'function'
        ? (menu.closest('.dsh-modal-overlay, .live-overlay') as HTMLElement | null)
        : null
    const hostParent = modalOverlay ?? doc?.body ?? null
    const shouldMount = Boolean(hostParent) && isNodeConnected(menu, doc) && !menu.hidden
    if (shouldMount && hostParent) {
      if (backing.parentElement !== hostParent) {
        if (modalOverlay) {
          prependChild(modalOverlay, backing)
        } else {
          hostParent.appendChild(backing)
        }
      }
      if (!observingBody && bodyObserver && doc.body) {
        observingBody = true
        bodyObserver.observe(doc.body, { childList: true, subtree: true })
      }
    } else {
      if (backing.parentElement) {
        backing.remove()
      }
      if (observingBody) {
        bodyObserver?.disconnect()
        observingBody = false
      }
    }
  }

  if (backing && MutationCtor) {
    bodyObserver = new MutationCtor(() => {
      if (!destroyed && !isNodeConnected(menu, doc)) {
        syncBacking()
      }
    })
  }

  const menuObserver = MutationCtor
    ? new MutationCtor(() => {
        if (!destroyed) syncBacking()
      })
    : null
  menuObserver?.observe(menu, {
    attributes: true,
    attributeFilter: ['hidden', 'data-side', 'data-align', 'style'],
  })

  syncBacking()
  if (backing && !isNodeConnected(menu, doc) && typeof queueMicrotask === 'function') {
    queueMicrotask(() => {
      if (!destroyed) syncBacking()
    })
  }

  const handle: MenuSurfaceHandle = {
    menu,
    viewport,
    backing,
    sync() {
      if (destroyed) return
      syncBacking()
      scrollHandle?.sync()
    },
    destroy() {
      if (destroyed) return
      destroyed = true
      menuObserver?.disconnect()
      if (observingBody) {
        bodyObserver?.disconnect()
        observingBody = false
      }
      stopHighlight?.()
      scrollHandle?.destroy()
      backing?.remove()
      menuSurfaceRegistry.delete(menu)
    },
  }

  menuSurfaceRegistry.set(menu, handle)
  return handle
}

/* ---------- 6. InfoTip 说明气泡命令式挂载器 ---------- */

export interface MountInfoTipBubbleOptions {
  id: string
  text: string
  className?: string
  side?: 'top' | 'bottom'
  align?: 'start' | 'end' | 'center'
  origin?: string
  zIndex?: number
  placement?: InfoTipBubblePlacementInput
}

export interface InfoTipBubblePlacementInput {
  left?: number
  right?: number
  top?: number
  bottom?: number
  maxWidth: number
  side?: 'top' | 'bottom'
  align?: 'start' | 'end' | 'center'
  origin?: string
}

export interface InfoTipBubbleHandle {
  node: HTMLDivElement
  body: HTMLDivElement
  setText: (next: string) => void
  syncPlacement: (placement: InfoTipBubblePlacementInput) => void
  destroy: () => void
}

let infoTipBubbleUid = 0

/**
 * 在 document.body 挂载标准 13px 磨砂 InfoTip 气泡（.hs-msurf.hs-msurf-compact.dsh-infotip-pop）及其配对 .hs-msurf-backing。
 */
export function mountInfoTipBubble(
  doc: Document,
  options: MountInfoTipBubbleOptions,
): InfoTipBubbleHandle {
  const anchorName = `--dsh-infotip-${++infoTipBubbleUid}`

  const node = doc.createElement('div')
  node.id = options.id
  node.setAttribute('id', options.id)
  node.setAttribute('role', 'tooltip')
  node.className = ['hs-msurf', 'hs-msurf-compact', 'dsh-infotip-pop', options.className]
    .filter(Boolean)
    .join(' ')
  node.setAttribute('data-menu-material', 'translucent')
  node.setAttribute('data-pop-anim', 'true')
  node.setAttribute('data-dsh-portal', '')
  node.style.setProperty('--dsh-menu-anchor', anchorName)

  const materialEl = doc.createElement('div')
  materialEl.className = 'hs-msurf-material'
  materialEl.setAttribute('aria-hidden', 'true')

  const body = doc.createElement('div')
  body.className = 'dsh-infotip-body'
  body.textContent = options.text

  node.appendChild(materialEl)
  node.appendChild(body)

  const backing = doc.createElement('div')
  backing.className = 'hs-msurf-backing hs-msurf-compact'
  backing.setAttribute('data-menu-backing', '')
  backing.setAttribute('data-dsh-portal', '')
  backing.setAttribute('data-pop-anim', 'true')
  backing.setAttribute('aria-hidden', 'true')
  backing.style.setProperty('--dsh-menu-anchor', anchorName)

  const applyDirectionalAttrs = (
    side?: 'top' | 'bottom',
    align?: 'start' | 'end' | 'center',
    origin?: string,
  ) => {
    if (side) {
      node.setAttribute('data-side', side)
      backing.setAttribute('data-side', side)
    }
    if (align) {
      node.setAttribute('data-align', align)
      backing.setAttribute('data-align', align)
    }
    if (origin) {
      node.style.setProperty('--dsh-pop-origin', origin)
      backing.style.setProperty('--dsh-pop-origin', origin)
    }
  }

  const applyPlacement = (placement: InfoTipBubblePlacementInput) => {
    setStylePxOrClear(node.style, 'left', 'left', placement.left)
    setStylePxOrClear(node.style, 'right', 'right', placement.right)
    setStylePxOrClear(node.style, 'top', 'top', placement.top)
    setStylePxOrClear(node.style, 'bottom', 'bottom', placement.bottom)
    setStylePxOrClear(node.style, 'max-width', 'maxWidth', placement.maxWidth)
    applyDirectionalAttrs(placement.side, placement.align, placement.origin)
  }

  applyDirectionalAttrs(options.side, options.align, options.origin)
  if (options.placement) {
    applyPlacement(options.placement)
  }

  const modalOverlays =
    typeof doc.querySelectorAll === 'function'
      ? Array.from(doc.querySelectorAll<HTMLElement>('.dsh-modal-overlay, .live-overlay.is-open'))
      : []
  const topModalOverlay = modalOverlays[modalOverlays.length - 1] ?? null
  const resolvedZ =
    typeof options.zIndex === 'number'
      ? options.zIndex
      : topModalOverlay
        ? 1300
        : undefined
  if (typeof resolvedZ === 'number') {
    node.style.zIndex = String(resolvedZ)
  }

  if (doc.body) {
    doc.body.appendChild(node)
    if (topModalOverlay) {
      prependChild(topModalOverlay, backing)
    } else {
      doc.body.appendChild(backing)
    }
  }

  let destroyed = false
  return {
    node,
    body,
    setText(next: string) {
      body.textContent = next
    },
    syncPlacement(placement: InfoTipBubblePlacementInput) {
      if (destroyed) return
      applyPlacement(placement)
    },
    destroy() {
      if (destroyed) return
      destroyed = true
      node.remove()
      backing.remove()
    },
  }
}

/* ---------- 7. 渐进增强原生 <select>（MenuSurface + ScrollArea + 单一高亮游标） ---------- */

export interface EnhanceSelectOptions {
  doc?: Document
  win?: Window | null
  uid?: (prefix: string) => string
  onOpen?: (close: (refocus?: boolean) => void) => void
  onClose?: () => void
  compact?: boolean
  buttonClassName?: string
  labelClassName?: string
  menuClassName?: string
  optionClassName?: string
}

export interface EnhanceSelectHandle {
  sync: () => void
  close: (refocus?: boolean) => void
  open: () => void
  btn: HTMLButtonElement
  isOpen: () => boolean
}

let selectUidCounter = 0
const enhancedSelectRegistry = new WeakMap<HTMLElement, EnhanceSelectHandle>()

const CHEVRON_DOWN_PATH = 'M3.5 6 8 10.5 12.5 6'
const CHECK_ICON_PATH = 'M3 8.5 6.5 12 13 4.5'

function getSelectOptions(select: HTMLSelectElement): HTMLOptionElement[] {
  if (select.options && typeof select.options.length === 'number') {
    return Array.from(select.options)
  }
  return Array.from(select.querySelectorAll('option')) as HTMLOptionElement[]
}

/**
 * 将包裹原生 <select> 的容器渐进增强为 MenuSurface 风格自定义 listbox，保留原 <select>.value 与 change 事件兼容。
 */
export function enhanceSelect(
  wrap: HTMLElement,
  options?: EnhanceSelectOptions,
): EnhanceSelectHandle {
  const cached = enhancedSelectRegistry.get(wrap)
  if (cached) return cached

  const activeDoc = options?.doc ?? wrap.ownerDocument
  const activeWin = options?.win ?? activeDoc?.defaultView ?? null
  const nextUid = options?.uid ?? ((prefix: string) => `${prefix}-${++selectUidCounter}`)

  const rawSelect = wrap.querySelector('select') as HTMLSelectElement | null
  if (!rawSelect) {
    const dummyBtn = activeDoc.createElement('button')
    dummyBtn.type = 'button'
    dummyBtn.disabled = true
    return {
      sync() {},
      close() {},
      open() {},
      btn: dummyBtn,
      isOpen: () => false,
    }
  }
  const select: HTMLSelectElement = rawSelect

  addClass(wrap, 'dsh-select-wrap')
  wrap.setAttribute('data-enhanced', 'true')
  select.setAttribute('aria-hidden', 'true')
  select.tabIndex = -1

  const labelEl = activeDoc.createElement('span')
  labelEl.className = ['dsh-select-val', options?.labelClassName].filter(Boolean).join(' ')

  const btn = activeDoc.createElement('button')
  btn.type = 'button'
  btn.className = [
    'dsh-select',
    options?.compact ? 'dsh-select-sm' : '',
    options?.buttonClassName,
  ]
    .filter(Boolean)
    .join(' ')
  btn.setAttribute('aria-haspopup', 'listbox')
  btn.setAttribute('aria-expanded', 'false')
  const initAriaLabel = select.getAttribute('aria-label')
  if (initAriaLabel) btn.setAttribute('aria-label', initAriaLabel)

  btn.appendChild(labelEl)
  btn.appendChild(createSvgIcon(activeDoc, CHEVRON_DOWN_PATH, 12, 'dsh-select-arrow'))
  wrap.appendChild(btn)

  let menu: HTMLDivElement | null = null
  let surface: MenuSurfaceHandle | null = null

  const sync = () => {
    const opts = getSelectOptions(select)
    const selectedIdx = typeof select.selectedIndex === 'number' ? select.selectedIndex : -1
    const curOpt =
      (selectedIdx >= 0 ? opts[selectedIdx] : undefined)
      ?? opts.find((o) => o.value === select.value)
      ?? opts[0]
    labelEl.textContent = curOpt?.textContent ?? ''
    btn.disabled = Boolean(select.disabled)

    if (select.hasAttribute('data-picked')) {
      btn.setAttribute('data-picked', select.getAttribute('data-picked') ?? '')
    } else {
      btn.removeAttribute('data-picked')
    }

    const ariaLabel = select.getAttribute('aria-label')
    if (ariaLabel) btn.setAttribute('aria-label', ariaLabel)
    else btn.removeAttribute('aria-label')

    const ariaInvalid = select.getAttribute('aria-invalid')
    if (ariaInvalid) btn.setAttribute('aria-invalid', ariaInvalid)
    else btn.removeAttribute('aria-invalid')

    if (btn.disabled && menu) {
      close(false)
    }

    if (menu) {
      if (ariaLabel) menu.setAttribute('aria-label', ariaLabel)
      else menu.removeAttribute('aria-label')
      const optionItems = Array.from(menu.querySelectorAll<HTMLElement>('[role="option"]'))
      for (const item of optionItems) {
        const val = item.getAttribute('data-value') ?? ''
        const isSel = val === select.value
        item.setAttribute('aria-selected', String(isSel))
      }
      surface?.sync()
    }
  }

  const onOutsidePointerDown = (e: Event) => {
    if (!wrap.contains(e.target as Node)) {
      close(false)
    }
  }

  function close(refocus = false): void {
    if (!menu) return
    activeDoc?.removeEventListener?.('pointerdown', onOutsidePointerDown, true)
    surface?.destroy()
    surface = null
    menu.remove()
    menu = null
    removeClass(wrap, 'is-open')
    btn.setAttribute('aria-expanded', 'false')
    btn.removeAttribute('aria-controls')
    btn.removeAttribute('aria-activedescendant')
    options?.onClose?.()
    if (refocus && isNodeConnected(btn, activeDoc)) {
      btn.focus?.({ preventScroll: true })
    }
  }

  function open(): void {
    if (btn.disabled) return
    if (menu) {
      close(true)
      return
    }
    options?.onOpen?.((refocus?: boolean) => close(refocus))

    const menuId = nextUid('sel')
    const opts = getSelectOptions(select)
    const nextMenu = activeDoc.createElement('div')
    nextMenu.className = ['dsh-select-menu', options?.menuClassName].filter(Boolean).join(' ')
    nextMenu.setAttribute('role', 'listbox')
    nextMenu.id = menuId
    nextMenu.setAttribute('id', menuId)
    nextMenu.tabIndex = -1
    const ariaLabel = select.getAttribute('aria-label')
    if (ariaLabel) nextMenu.setAttribute('aria-label', ariaLabel)

    for (const opt of opts) {
      const value = opt.value
      const selected = value === select.value
      const itemBtn = activeDoc.createElement('button')
      itemBtn.type = 'button'
      itemBtn.className = ['hs-msurf-item', 'hs-fb-item', options?.optionClassName]
        .filter(Boolean)
        .join(' ')
      itemBtn.setAttribute('role', 'option')
      itemBtn.tabIndex = -1
      itemBtn.setAttribute('tabindex', '-1')
      if (opt.disabled) {
        itemBtn.disabled = true
        itemBtn.setAttribute('disabled', '')
      }
      itemBtn.setAttribute('data-value', value)
      itemBtn.setAttribute('aria-selected', String(selected))

      const itemLabel = activeDoc.createElement('span')
      itemLabel.className = 'hs-fb-label'
      itemLabel.textContent = opt.textContent ?? ''

      const itemCheck = activeDoc.createElement('span')
      itemCheck.className = 'hs-fb-check'
      itemCheck.setAttribute('aria-hidden', 'true')
      itemCheck.appendChild(createSvgIcon(activeDoc, CHECK_ICON_PATH, 13))

      itemBtn.appendChild(itemLabel)
      itemBtn.appendChild(itemCheck)
      itemBtn.addEventListener('click', () => {
        if (opt.disabled) return
        select.value = value
        const idx = getSelectOptions(select).findIndex((o) => o.value === value)
        if (idx >= 0) {
          try {
            select.selectedIndex = idx
          } catch {
            /* ignore readonly selectedIndex in mock DOM */
          }
        }
        sync()
        close(true)
        const EvtCtor =
          (activeWin as unknown as { Event?: typeof Event } | null)?.Event ?? globalThis.Event
        if (typeof EvtCtor === 'function') {
          select.dispatchEvent(new EvtCtor('change', { bubbles: true }))
        } else {
          select.dispatchEvent?.({ type: 'change', bubbles: true } as unknown as Event)
        }
      })
      nextMenu.appendChild(itemBtn)
    }

    nextMenu.addEventListener('keydown', (e: KeyboardEvent) => {
      if (isImeComposing(e)) return
      if (e.key === 'Escape') {
        e.preventDefault?.()
        e.stopPropagation?.()
        close(true)
        return
      }
      if (e.key === 'Tab') {
        close(true)
        return
      }
      stepMenuKey(e, nextMenu, '[role="option"]', activeDoc)
    })

    menu = nextMenu
    surface = mountMenuSurface(nextMenu, {
      compact: options?.compact,
      material: 'translucent',
      scrollable: true,
      itemSelector: '[role="option"]',
      win: activeWin,
    })

    addClass(wrap, 'is-open')
    wrap.appendChild(nextMenu)

    btn.setAttribute('aria-expanded', 'true')
    btn.setAttribute('aria-controls', menuId)
    activeDoc?.addEventListener?.('pointerdown', onOutsidePointerDown, true)
    fitMenuInViewport(nextMenu, activeWin)
    surface.sync()

    const allOptions = Array.from(nextMenu.querySelectorAll<HTMLButtonElement>('[role="option"]'))
    const cur =
      allOptions.find((el) => !el.disabled && el.getAttribute('aria-selected') === 'true')
      ?? allOptions.find((el) => !el.disabled)
      ?? null
    cur?.focus?.({ preventScroll: true })
    if (cur && activeDoc?.documentElement?.getAttribute('data-input-modality') === 'keyboard') {
      cur.setAttribute('data-highlighted', 'true')
      nextMenu.setAttribute('data-has-highlight', 'true')
    }
    cur?.scrollIntoView?.({ block: 'nearest' })
    surface.sync()
  }

  btn.addEventListener('click', () => {
    if (btn.disabled) return
    if (menu) close(true)
    else open()
  })

  btn.addEventListener('keydown', (e: KeyboardEvent) => {
    if (isImeComposing(e)) return
    if ((e.key === 'ArrowDown' || e.key === 'ArrowUp') && menu === null) {
      e.preventDefault?.()
      open()
    }
  })

  select.addEventListener('click', (e: Event) => {
    e.preventDefault?.()
    if (!btn.disabled && isNodeConnected(btn, activeDoc)) {
      btn.focus?.({ preventScroll: true })
    }
  })

  select.addEventListener('change', () => sync())

  const MutationCtor =
    (activeWin as unknown as { MutationObserver?: typeof MutationObserver } | null)
      ?.MutationObserver ?? globalThis.MutationObserver
  if (MutationCtor) {
    const mo = new MutationCtor(() => sync())
    mo.observe(select, {
      attributes: true,
      childList: true,
      subtree: true,
      attributeFilter: ['data-picked', 'disabled', 'aria-label', 'aria-invalid'],
    })
  }

  sync()

  const handle: EnhanceSelectHandle = {
    sync,
    close,
    open,
    btn,
    isOpen: () => menu !== null,
  }
  enhancedSelectRegistry.set(wrap, handle)
  return handle
}
