import React, {
  forwardRef,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
  type CSSProperties,
  type InputHTMLAttributes,
  type KeyboardEvent,
  type MouseEvent as ReactMouseEvent,
  type PointerEvent as ReactPointerEvent,
  type ReactNode,
  type TextareaHTMLAttributes,
} from 'react'
import { createPortal } from 'react-dom'
import { MenuSurface } from './MenuSurface'
import { ScrollArea } from './ScrollArea'
import { useAnchoredPlacement } from './anchored-position'
import { isImeComposing } from './host-bridge'
import { CheckIcon, ChevronDownIcon, CloseIcon, EyeIcon, EyeOffIcon, SearchIcon } from './icons'
import { didPointerActuallyMove } from './motion'
import { OverlayParentContext, useOverlayLayer } from './overlay-stack'

export type InputSize = 'md' | 'lg' | 'dialog'

export interface InputProps extends Omit<InputHTMLAttributes<HTMLInputElement>, 'size'> {
  /** md / dialog 统一 36px 胶囊；lg (44px) 仅限页面级主输入场景。 */
  size?: InputSize
  invalid?: boolean
  /** 安全回车回调：内置 isImeComposing 守卫，拦截 CJK 拼音选词 Enter。 */
  onEnter?: (value: string, event: KeyboardEvent<HTMLInputElement>) => void
}

export const Input = forwardRef<HTMLInputElement, InputProps>(function Input(
  { size = 'md', invalid = false, onEnter, onKeyDown, className, ...rest },
  ref,
) {
  const sizeClass =
    size === 'lg' ? ' dsh-input-lg' : size === 'dialog' ? ' dsh-input-dialog' : ''
  const errorClass = invalid ? ' is-error dsh-input-error' : ''

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    onKeyDown?.(event)
    if (event.defaultPrevented) return
    if (event.key === 'Enter' && onEnter && !isImeComposing(event)) {
      onEnter(event.currentTarget.value, event)
    }
  }

  return (
    <input
      ref={ref}
      aria-invalid={invalid || rest['aria-invalid'] || undefined}
      onKeyDown={onEnter || onKeyDown ? handleKeyDown : undefined}
      className={`dsh-input${sizeClass}${errorClass}${className ? ` ${className}` : ''}`}
      {...rest}
    />
  )
})

export interface SearchInputProps
  extends Omit<InputHTMLAttributes<HTMLInputElement>, 'onChange' | 'value' | 'size'> {
  value: string
  onChange: (value: string) => void
  clearLabel?: string
  /** 默认渲染统一 SearchIcon；传 null 可隐藏前导图标。 */
  leadingIcon?: ReactNode | null
  /** 安全回车回调：内置 isImeComposing 守卫。 */
  onEnter?: (value: string, event: KeyboardEvent<HTMLInputElement>) => void
}

export const SearchInput = forwardRef<HTMLInputElement, SearchInputProps>(function SearchInput(
  {
    value,
    onChange,
    clearLabel = '清空搜索',
    leadingIcon,
    onEnter,
    onKeyDown,
    disabled,
    className,
    ...rest
  },
  ref,
) {
  const localRef = useRef<HTMLInputElement | null>(null)
  const resolvedIcon = leadingIcon === undefined ? <SearchIcon size={14} inline={false} /> : leadingIcon

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    onKeyDown?.(event)
    if (event.defaultPrevented) return
    if (event.key === 'Enter' && onEnter && !isImeComposing(event)) {
      onEnter(value, event)
    }
  }

  const handleBoxMouseDown = (event: ReactMouseEvent<HTMLDivElement>) => {
    if (disabled) return
    const target = event.target
    if (target instanceof Element && target.closest('input, button')) return
    event.preventDefault()
    localRef.current?.focus?.()
  }

  return (
    <div
      className={`dsh-search${disabled ? ' is-disabled' : ''}${className ? ` ${className}` : ''}`}
      onMouseDown={handleBoxMouseDown}
    >
      {resolvedIcon !== null && (
        <span className="dsh-search-ico" aria-hidden="true">
          {resolvedIcon}
        </span>
      )}
      <input
        ref={(node) => {
          localRef.current = node
          if (typeof ref === 'function') ref(node)
          else if (ref) ref.current = node
        }}
        type="text"
        value={value}
        disabled={disabled}
        onChange={(event) => onChange(event.target.value)}
        onKeyDown={onEnter || onKeyDown ? handleKeyDown : undefined}
        {...rest}
      />
      {value.length > 0 && !disabled && (
        <button
          type="button"
          className="dsh-search-clear"
          aria-label={clearLabel}
          onClick={() => {
            onChange('')
            localRef.current?.focus?.()
          }}
        >
          <CloseIcon size={12} inline={false} />
        </button>
      )}
    </div>
  )
})

export interface PasswordInputProps
  extends Omit<InputHTMLAttributes<HTMLInputElement>, 'type' | 'size'> {
  invalid?: boolean
  visible?: boolean
  defaultVisible?: boolean
  onVisibleChange?: (visible: boolean) => void
  revealLabel?: string
  hideLabel?: string
  trailingAction?: ReactNode
  onEnter?: (value: string, event: KeyboardEvent<HTMLInputElement>) => void
}

export const PasswordInput = forwardRef<HTMLInputElement, PasswordInputProps>(function PasswordInput(
  {
    invalid = false,
    visible,
    defaultVisible = false,
    onVisibleChange,
    revealLabel = '显示密钥',
    hideLabel = '隐藏密钥',
    trailingAction,
    onEnter,
    onKeyDown,
    disabled,
    className,
    ...rest
  },
  ref,
) {
  const localRef = useRef<HTMLInputElement | null>(null)
  const [uncontrolledVisible, setUncontrolledVisible] = useState(defaultVisible)
  const isShown = visible !== undefined ? visible : uncontrolledVisible

  const toggleVisible = () => {
    if (disabled) return
    const next = !isShown
    if (visible === undefined) setUncontrolledVisible(next)
    onVisibleChange?.(next)
  }

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    onKeyDown?.(event)
    if (event.defaultPrevented) return
    if (event.key === 'Enter' && onEnter && !isImeComposing(event)) {
      onEnter(event.currentTarget.value, event)
    }
  }

  const handleBoxMouseDown = (event: ReactMouseEvent<HTMLDivElement>) => {
    if (disabled) return
    const target = event.target
    if (target instanceof Element && target.closest('input, button')) return
    event.preventDefault()
    localRef.current?.focus?.()
  }

  const boxNode = (
    <div
      className={`dsh-pwd-box${invalid ? ' is-error' : ''}${disabled ? ' is-disabled' : ''}${trailingAction === undefined && className ? ` ${className}` : ''}`}
      onMouseDown={handleBoxMouseDown}
    >
      <input
        ref={(node) => {
          localRef.current = node
          if (typeof ref === 'function') ref(node)
          else if (ref) ref.current = node
        }}
        type={isShown ? 'text' : 'password'}
        disabled={disabled}
        aria-invalid={invalid || rest['aria-invalid'] || undefined}
        onKeyDown={onEnter || onKeyDown ? handleKeyDown : undefined}
        {...rest}
      />
      <button
        type="button"
        className="dsh-pwd-eye"
        disabled={disabled}
        aria-label={isShown ? hideLabel : revealLabel}
        aria-pressed={isShown}
        onClick={toggleVisible}
      >
        {isShown ? <EyeOffIcon size={15} inline={false} /> : <EyeIcon size={15} inline={false} />}
      </button>
    </div>
  )

  if (trailingAction === undefined) return boxNode

  return (
    <div className={`dsh-pwd-wrap${className ? ` ${className}` : ''}`}>
      {boxNode}
      {trailingAction}
    </div>
  )
})

export interface SelectOption<T extends string = string> {
  value: T
  label: ReactNode
  disabled?: boolean
  icon?: ReactNode
  description?: ReactNode
  /** 可选分组标题：连续同组选项会自动渲染在同一个语义分组下。 */
  group?: string
}

export interface SelectProps<T extends string = string> {
  options: readonly SelectOption<T>[]
  value?: T
  onChange: (value: T) => void
  size?: 'md' | 'sm'
  placeholder?: ReactNode
  emptyLabel?: ReactNode
  disabled?: boolean
  invalid?: boolean
  ariaLabel?: string
  id?: string
  className?: string
  align?: 'start' | 'end'
  side?: 'bottom' | 'top'
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
}

function extractOptionSearchText<T extends string>(
  opt: SelectOption<T>,
  el: HTMLElement | null | undefined,
): string {
  if (typeof opt.label === 'string' || typeof opt.label === 'number') {
    return `${String(opt.label)} ${opt.value}`.toLowerCase()
  }
  const domText = el?.querySelector('.hs-fb-label')?.textContent ?? el?.textContent ?? ''
  return `${domText} ${opt.value}`.toLowerCase()
}

/**
 * 04-A 自定义胶囊下拉框（36px md / 28px sm 正圆胶囊触发器 + Portal 锚定 MenuSurface 柔焦微边毛玻璃列表）：
 * - 自动视口边缘翻转、Modal 内动态抬升 z-index、LIFO Escape 阻断穿透；
 * - 单一高亮游标（消除鼠标悬停与键盘焦点双高亮冲突）+ Tab 归还表单焦点序 + 轻量字符前缀 Typeahead。
 */
export function Select<T extends string = string>({
  options,
  value,
  onChange,
  size = 'md',
  placeholder = '请选择',
  emptyLabel = '暂无选项',
  disabled = false,
  invalid = false,
  ariaLabel,
  id,
  className,
  align = 'start',
  side = 'bottom',
  open: controlledOpen,
  defaultOpen = false,
  onOpenChange,
}: SelectProps<T>) {
  const listboxId = useId()
  const triggerRef = useRef<HTMLButtonElement | null>(null)
  const panelRef = useRef<HTMLDivElement | null>(null)
  const optionRefs = useRef<Array<HTMLButtonElement | null>>([])
  const openViaRef = useRef<'down' | 'up' | null>(null)
  const wasOpenRef = useRef(false)
  const lastPointerRef = useRef<{ x: number; y: number } | null>(null)
  const typeaheadRef = useRef<{ buf: string; lastAt: number }>({ buf: '', lastAt: 0 })

  const [uncontrolledOpen, setUncontrolledOpen] = useState(defaultOpen)
  const isOpen = !disabled && (controlledOpen !== undefined ? controlledOpen : uncontrolledOpen)

  const setOpen = (next: boolean) => {
    if (disabled && next) return
    if (controlledOpen === undefined) setUncontrolledOpen(next)
    onOpenChange?.(next)
  }

  const enabledIndices = useMemo(
    () =>
      options.reduce<number[]>((acc, opt, idx) => {
        if (!opt.disabled) acc.push(idx)
        return acc
      }, []),
    [options],
  )

  const selectedIndex = useMemo(
    () => (value === undefined ? -1 : options.findIndex((opt) => opt.value === value)),
    [options, value],
  )
  const selectedOption = selectedIndex >= 0 ? options[selectedIndex] : undefined

  const [activeIndex, setActiveIndex] = useState<number>(() => selectedIndex)
  const [highlightedIndex, setHighlightedIndex] = useState<number>(-1)

  const placement = useAnchoredPlacement({
    open: isOpen,
    anchorRef: triggerRef,
    panelRef,
    side,
    align,
    gap: 5,
    margin: 8,
  })

  const { layerId, zIndex } = useOverlayLayer({
    open: isOpen,
    tier: 'select',
    containsNode: (node) =>
      Boolean(triggerRef.current?.contains(node) || panelRef.current?.contains(node)),
    onEscape: () => {
      setOpen(false)
      triggerRef.current?.focus?.()
    },
    onPointerDownOutside: () => {
      setOpen(false)
    },
  })

  useEffect(() => {
    if (!isOpen) {
      wasOpenRef.current = false
      openViaRef.current = null
      lastPointerRef.current = null
      typeaheadRef.current = { buf: '', lastAt: 0 }
      setHighlightedIndex(-1)
      return undefined
    }

    const justOpened = !wasOpenRef.current
    wasOpenRef.current = true
    if (justOpened) {
      const via = openViaRef.current
      openViaRef.current = null
      if (via !== null) {
        const targetIdx =
          selectedIndex >= 0 && !options[selectedIndex]?.disabled
            ? selectedIndex
            : via === 'up'
              ? (enabledIndices[enabledIndices.length - 1] ?? -1)
              : (enabledIndices[0] ?? -1)
        setActiveIndex(targetIdx)
        setHighlightedIndex(targetIdx)
        if (targetIdx >= 0) {
          const focusNode = () => optionRefs.current[targetIdx]?.focus?.()
          if (typeof requestAnimationFrame === 'function') requestAnimationFrame(focusNode)
          else focusNode()
        }
      } else {
        setActiveIndex(selectedIndex)
        setHighlightedIndex(-1)
        if (selectedIndex >= 0) {
          optionRefs.current[selectedIndex]?.scrollIntoView?.({ block: 'nearest' })
        }
        const focusPanel = () => panelRef.current?.focus?.({ preventScroll: true })
        if (typeof requestAnimationFrame === 'function') requestAnimationFrame(focusPanel)
        else focusPanel()
      }
    }

    if (typeof window === 'undefined') return undefined
    const onWinBlur = () => setOpen(false)
    window.addEventListener('blur', onWinBlur)
    return () => {
      window.removeEventListener('blur', onWinBlur)
    }
  }, [isOpen, selectedIndex, enabledIndices, options])

  const focusOptionAt = (index: number) => {
    setActiveIndex(index)
    setHighlightedIndex(index)
    const node = optionRefs.current[index]
    node?.focus?.()
    node?.scrollIntoView?.({ block: 'nearest' })
  }

  const chooseOption = (opt: SelectOption<T>) => {
    if (opt.disabled) return
    onChange(opt.value)
    setOpen(false)
    triggerRef.current?.focus?.()
  }

  const matchTypeahead = (char: string, baseIdx: number): number => {
    if (enabledIndices.length === 0) return -1
    const now = Date.now()
    const withinWindow = now - typeaheadRef.current.lastAt <= 500
    const nextBuf = withinWindow ? `${typeaheadRef.current.buf}${char.toLowerCase()}` : char.toLowerCase()
    typeaheadRef.current = { buf: nextBuf, lastAt: now }

    const startPos = enabledIndices.indexOf(baseIdx)
    const ordered: number[] = []
    for (let offset = 1; offset <= enabledIndices.length; offset += 1) {
      const idx = enabledIndices[(Math.max(0, startPos) + offset) % enabledIndices.length]
      if (idx !== undefined) ordered.push(idx)
    }

    // 连续按同一个字母（如 "aa"）时循环切换该首字母开头的项
    const allSameChar = nextBuf.length > 1 && nextBuf.split('').every((c) => c === nextBuf[0])
    const query = allSameChar ? nextBuf[0]! : nextBuf

    for (const idx of ordered) {
      const opt = options[idx]
      if (opt && extractOptionSearchText(opt, optionRefs.current[idx]).startsWith(query)) {
        return idx
      }
    }
    for (const idx of ordered) {
      const opt = options[idx]
      if (opt && extractOptionSearchText(opt, optionRefs.current[idx]).includes(query)) {
        return idx
      }
    }
    return -1
  }

  const isPrintableTypeahead = (event: KeyboardEvent<HTMLElement>): boolean => {
    if (event.ctrlKey || event.metaKey || event.altKey || isImeComposing(event)) return false
    if (event.key.length !== 1) return false
    if (event.key === ' ' && Date.now() - typeaheadRef.current.lastAt > 500) return false
    return true
  }

  const navigateStep = (key: string, fromIndex: number) => {
    if (enabledIndices.length === 0) return
    let targetIdx: number | undefined
    if (key === 'Home') {
      targetIdx = enabledIndices[0]
    } else if (key === 'End') {
      targetIdx = enabledIndices[enabledIndices.length - 1]
    } else if (key === 'ArrowDown') {
      if (fromIndex >= 0) {
        const pos = enabledIndices.indexOf(fromIndex)
        targetIdx =
          pos >= 0
            ? enabledIndices[(pos + 1) % enabledIndices.length]
            : enabledIndices[0]
      } else {
        targetIdx = enabledIndices[0]
      }
    } else if (fromIndex >= 0) {
      const pos = enabledIndices.indexOf(fromIndex)
      targetIdx =
        pos >= 0
          ? enabledIndices[(pos - 1 + enabledIndices.length) % enabledIndices.length]
          : enabledIndices[enabledIndices.length - 1]
    } else {
      targetIdx = enabledIndices[enabledIndices.length - 1]
    }
    if (targetIdx !== undefined) focusOptionAt(targetIdx)
  }

  const handleTriggerKeyDown = (event: KeyboardEvent<HTMLButtonElement>) => {
    if (isImeComposing(event) || disabled) return
    if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
      event.preventDefault()
      const dir = event.key === 'ArrowUp' ? 'up' : 'down'
      if (!isOpen) {
        openViaRef.current = dir
        setOpen(true)
      } else {
        const anchorIdx = highlightedIndex >= 0 ? highlightedIndex : selectedIndex
        const targetIdx =
          anchorIdx >= 0 && !options[anchorIdx]?.disabled
            ? anchorIdx
            : dir === 'up'
              ? (enabledIndices[enabledIndices.length - 1] ?? -1)
              : (enabledIndices[0] ?? -1)
        if (targetIdx >= 0) focusOptionAt(targetIdx)
      }
    } else if (event.key === 'Escape' && isOpen) {
      event.preventDefault()
      event.stopPropagation?.()
      setOpen(false)
    } else if (!isOpen && isPrintableTypeahead(event)) {
      const matchedIdx = matchTypeahead(event.key, selectedIndex)
      if (matchedIdx >= 0 && options[matchedIdx]) {
        event.preventDefault()
        onChange(options[matchedIdx]!.value)
      }
    }
  }

  const handlePanelKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (isImeComposing(event)) return
    if (event.target !== panelRef.current) return
    if (
      event.key === 'ArrowDown'
      || event.key === 'ArrowUp'
      || event.key === 'Home'
      || event.key === 'End'
    ) {
      event.preventDefault()
      const base = highlightedIndex >= 0 ? highlightedIndex : selectedIndex
      navigateStep(event.key, base)
    } else if (event.key === 'Enter' && highlightedIndex >= 0 && options[highlightedIndex]) {
      event.preventDefault()
      chooseOption(options[highlightedIndex]!)
    } else if (event.key === 'Escape') {
      event.preventDefault()
      event.stopPropagation?.()
      setOpen(false)
      triggerRef.current?.focus?.()
    } else if (event.key === 'Tab') {
      triggerRef.current?.focus?.()
      setOpen(false)
    } else if (isPrintableTypeahead(event)) {
      const base = highlightedIndex >= 0 ? highlightedIndex : selectedIndex
      const matchedIdx = matchTypeahead(event.key, base)
      if (matchedIdx >= 0) {
        event.preventDefault()
        focusOptionAt(matchedIdx)
      }
    }
  }

  const handleOptionKeyDown = (
    event: KeyboardEvent<HTMLButtonElement>,
    currentIndex: number,
    opt: SelectOption<T>,
  ) => {
    if (isImeComposing(event)) return
    if (
      event.key === 'ArrowDown'
      || event.key === 'ArrowUp'
      || event.key === 'Home'
      || event.key === 'End'
    ) {
      event.preventDefault()
      const base = highlightedIndex >= 0 ? highlightedIndex : currentIndex
      navigateStep(event.key, base)
    } else if (isPrintableTypeahead(event)) {
      const matchedIdx = matchTypeahead(event.key, currentIndex)
      if (matchedIdx >= 0) {
        event.preventDefault()
        focusOptionAt(matchedIdx)
      }
    } else if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault()
      chooseOption(opt)
    } else if (event.key === 'Escape') {
      event.preventDefault()
      event.stopPropagation?.()
      setOpen(false)
      triggerRef.current?.focus?.()
    } else if (event.key === 'Tab') {
      triggerRef.current?.focus?.()
      setOpen(false)
    }
  }

  const handleOptionPointerMove = (
    event: ReactPointerEvent<HTMLButtonElement>,
    idx: number,
    opt: SelectOption<T>,
  ) => {
    if (opt.disabled || !didPointerActuallyMove(lastPointerRef, event)) return
    if (highlightedIndex !== idx) {
      setHighlightedIndex(idx)
    }
    const panel = panelRef.current
    const doc = panel?.ownerDocument
    if (panel && doc && doc.activeElement && doc.activeElement !== panel && panel.contains(doc.activeElement)) {
      panel.focus?.({ preventScroll: true })
    }
  }

  const handleListPointerLeave = () => {
    lastPointerRef.current = null
    const panel = panelRef.current
    const doc = panel?.ownerDocument
    if (!doc || doc.activeElement === panel) {
      setHighlightedIndex(-1)
    }
  }

  const triggerWidth = triggerRef.current?.offsetWidth
  const resolvedSide = placement?.side ?? side
  const resolvedListMaxHeight = placement ? Math.min(232, placement.maxHeight) : 232
  const portalStyle: CSSProperties = {
    position: 'fixed',
    zIndex,
    minWidth: triggerWidth && triggerWidth > 0 ? `${triggerWidth}px` : '156px',
    maxWidth: 'min(360px, calc(100vw - 16px))',
    left: placement?.left ?? 0,
    top: placement?.top ?? 0,
    visibility:
      typeof window !== 'undefined' && placement === null ? 'hidden' : 'visible',
  }

  const renderOptionButton = (opt: SelectOption<T>, idx: number) => {
    const selected = value !== undefined && opt.value === value
    const isHighlighted = idx === highlightedIndex
    return (
      <button
        key={opt.value}
        ref={(node) => {
          optionRefs.current[idx] = node
        }}
        type="button"
        role="option"
        disabled={opt.disabled}
        aria-selected={selected}
        data-highlighted={isHighlighted ? 'true' : undefined}
        tabIndex={idx === activeIndex ? 0 : -1}
        className="hs-msurf-item hs-fb-item"
        onClick={() => chooseOption(opt)}
        onPointerMove={(event) => handleOptionPointerMove(event, idx, opt)}
        onKeyDown={(event) => handleOptionKeyDown(event, idx, opt)}
      >
        {opt.icon !== undefined && (
          <span className="hs-fb-icon" aria-hidden="true">
            {opt.icon}
          </span>
        )}
        <span className="hs-fb-label">{opt.label}</span>
        {selected && (
          <span className="hs-fb-check" aria-hidden="true">
            <CheckIcon size={13} inline={false} />
          </span>
        )}
        {opt.description !== undefined && (
          <span className="hs-fb-kbd dsh-select-desc">{opt.description}</span>
        )}
      </button>
    )
  }

  const renderOptionsWithGroups = (): ReactNode => {
    if (options.length === 0) {
      return <div className="dsh-select-empty">{emptyLabel}</div>
    }
    const nodes: ReactNode[] = []
    let i = 0
    while (i < options.length) {
      const opt = options[i]!
      if (opt.group) {
        const groupName = opt.group
        const groupItems: ReactNode[] = []
        const startIdx = i
        while (i < options.length && options[i]?.group === groupName) {
          groupItems.push(renderOptionButton(options[i]!, i))
          i += 1
        }
        nodes.push(
          <div key={`grp-${startIdx}-${groupName}`} role="group" aria-label={groupName} className="hs-fb-group">
            <div className="hs-fb-heading">{groupName}</div>
            {groupItems}
          </div>,
        )
      } else {
        nodes.push(renderOptionButton(opt, i))
        i += 1
      }
    }
    return nodes
  }

  const canPortal = typeof document !== 'undefined' && Boolean(document.body)

  const menuElement = isOpen ? (
    <OverlayParentContext.Provider value={layerId}>
      <MenuSurface
        ref={panelRef}
        id={listboxId}
        role="listbox"
        tabIndex={-1}
        aria-label={ariaLabel}
        aria-labelledby={ariaLabel === undefined && id ? id : undefined}
        compact={size === 'sm'}
        origin={placement?.origin}
        data-dsh-portal={canPortal ? '' : undefined}
        data-menu-managed=""
        data-side={resolvedSide}
        data-align={align}
        data-pop-anim={placement !== null || typeof window === 'undefined' ? 'true' : undefined}
        className="dsh-select-portal-menu"
        style={portalStyle}
        onKeyDown={handlePanelKeyDown}
        onPointerLeave={handleListPointerLeave}
      >
        <ScrollArea
          maxHeight={resolvedListMaxHeight}
          thumbThreshold={1.05}
          className="dsh-select-scroll"
          viewportClassName="dsh-select-list"
        >
          {renderOptionsWithGroups()}
        </ScrollArea>
      </MenuSurface>
    </OverlayParentContext.Provider>
  ) : null

  return (
    <div className={`dsh-select-wrap${isOpen ? ' is-open' : ''}${className ? ` ${className}` : ''}`}>
      <button
        ref={triggerRef}
        id={id}
        type="button"
        disabled={disabled}
        aria-label={ariaLabel}
        aria-invalid={invalid || undefined}
        aria-haspopup="listbox"
        aria-expanded={isOpen}
        aria-controls={isOpen ? listboxId : undefined}
        className={`dsh-select${size === 'sm' ? ' dsh-select-sm' : ''}${invalid ? ' is-error' : ''}`}
        onClick={(event) => {
          openViaRef.current = event.detail === 0 ? 'down' : null
          setOpen(!isOpen)
        }}
        onKeyDown={handleTriggerKeyDown}
      >
        {selectedOption?.icon !== undefined && (
          <span className="dsh-select-ico" aria-hidden="true">
            {selectedOption.icon}
          </span>
        )}
        <span className={`dsh-select-val${selectedOption === undefined ? ' is-placeholder' : ''}`}>
          {selectedOption ? selectedOption.label : placeholder}
        </span>
        <ChevronDownIcon size={12} inline={false} className="dsh-select-arrow" />
      </button>
      {menuElement !== null
        ? canPortal
          ? createPortal(menuElement, document.body)
          : menuElement
        : null}
    </div>
  )
}

export interface TextareaProps extends TextareaHTMLAttributes<HTMLTextAreaElement> {
  invalid?: boolean
  code?: boolean
}

export const Textarea = forwardRef<HTMLTextAreaElement, TextareaProps>(function Textarea(
  { invalid = false, code = false, className, ...rest },
  ref,
) {
  return (
    <textarea
      ref={ref}
      aria-invalid={invalid || rest['aria-invalid'] || undefined}
      className={`dsh-textarea${code ? ' is-code' : ''}${invalid ? ' is-error' : ''}${className ? ` ${className}` : ''}`}
      {...rest}
    />
  )
})

