export type IconButtonSize = 'md' | 'sm' | 'xs'
export type IconButtonVariant = 'ghost' | 'outline' | 'danger-solid' | 'danger-ghost'

export type IconButtonProps = ButtonHTMLAttributes<HTMLButtonElement> & {
  /** 标准三档正圆尺寸：md=36px / sm=28px / xs=20px（内置 ::after 隐形热区外扩）。 */
  size?: IconButtonSize
  /** 向后兼容旧调用：round/sm 映射为 28px 正圆，xs 映射为 20px 正圆。 */
  shape?: 'round' | 'sm' | 'xs'
  variant?: IconButtonVariant
  tip?: string
}

/**
 * 03 纯图标正圆按钮（36 / 28 / 20px 全系 50% 正圆 + 永久锁定 corner-shape: round）：
 * 20px 微按钮内置透明 ::after 热区外扩（桌面 28x28 / 触屏 36x36，紧密操作栏自动收窄至 -2px 防碰撞），
 * 按压采用 60ms scale(0.96) 迅捷下压与 150ms 无过冲回弹。
 */
export const IconButton = forwardRef<HTMLButtonElement, IconButtonProps>(function IconButton(
  { size, shape = 'round', variant, tip, className, children, ...rest },
  ref,
) {
  const resolvedSize: IconButtonSize = size ?? (shape === 'xs' ? 'xs' : 'sm')
  const resolvedVariant: IconButtonVariant =
    variant ?? (shape === 'sm' && size === undefined ? 'outline' : 'ghost')

  const sizeClass =
    resolvedSize === 'md'
      ? 'dsh-ibtn-md icon-btn-md'
      : resolvedSize === 'xs'
        ? 'dsh-ibtn-xs icon-btn-xs'
        : `dsh-ibtn-round icon-btn-round${shape === 'sm' ? ' dsh-ibtn-sm' : ''}`

  const variantClass =
    resolvedVariant === 'outline'
      ? ' icon-btn-outline'
      : resolvedVariant === 'danger-solid'
        ? ' icon-btn-danger-solid'
        : resolvedVariant === 'danger-ghost'
          ? ' icon-btn-danger-ghost'
          : ''

  return (
    <button
      ref={ref}
      type="button"
      data-hs-tip={tip}
      className={`dsh-ibtn ${sizeClass}${variantClass}${className ? ` ${className}` : ''}`}
      {...rest}
    >
      {children}
    </button>
  )
})

